/// The fingerprint of the last statement of the file the views stand in, as the parser both the
/// layer's items and its canonical reading (`item_canonical`) fingerprint by.
fn last_fp(body: string) -> int {
    let p = parse_source(
        "fn none() -> string { \"\" }\ntype Words = fn() -> string\ncomponent said(content: string) {\n    words: Words = Words(none)\n}\nstate n: int = 0\n" +
            body,
    )
    p.store.stmt_fingerprint(p.stmts.last()!)
}

spec "compiler — a view's declaration fingerprint follows its sited text" {
    given "two views that differ only inside a sited hole" {
        then "an edit inside the hole moves the declaration's fingerprint" {
            last_fp("fn v() -> said { said \"a \${n}\" }\n") != last_fp("fn v() -> said { said \"a \${n + 1}\" }\n")
        }
    }
    given "two views written the same way" {
        then "the same source fingerprints alike" {
            last_fp("fn v() -> said { said \"a \${n}\" }\n") == last_fp("fn v() -> said { said \"a \${n}\" }\n")
        }
    }
}
EOF
