/// After asking only whether a call to `asked` may park, on a fresh survey: whether the walk met
/// each fn of `names`, `y` where it did and `n` where it didn't.
fn met_after(asked: string, names: List<string>) -> string {
    let j = cancel_judged(cancel_cycle("avra_fiber_sleep(1)"))
    let survey = task_survey(j.engine)
    let _ = survey.finds(called(j, asked), map_cell(), (f: CancelFact) -> f.parks)
    let met = survey.met.get()
    [if met.has(called(j, n).key()) { "y" } else { "n" } for n in names].join("")
}

/// The body a call of the entry's free fn `name` runs.
fn called(j: Judged, name: string) -> BodyAt {
    body_at(
        CalledFn {
            file: j.entry,
            name: name,
            symbol: declared_symbol(j.entry, name),
            external: false,
            plain: true,
            owner: null,
            of: null,
        },
    )
}

