// A fn's cancel bits are settled with its strongly-connected set alone: a cycle takes what a
// member outside it reaches, a cycle with no waiter reaches nothing, and asking one fn settles
// no fn it does not call. `CancelBits` is a family by name; the keys are spelled through
// `family_ordinal`.
// The old path's cells, asked in an order; what a fn reaches on the layer is cancel_scc_test.av.
use @std.avrac.testing.old_path.{test_workspace}
use compiler.{Workspace}
use compiler.host.{memory_host}
use core.{DeclId}
use @std.relation.engine.{Key}
fn bits_key(d: DeclId) -> Key { Key { family: family_ordinal("CancelBits"), arg: d.index } }
fn cancel_workspace(main: string) -> Workspace {
    let ws = test_workspace(
        memory_host(
            {
                "/w/avra.toml": "[package]\nname = \"app\"\nversion = \"0.1.0\"\n",
                "/w/src/main.av": main,
            },
            ["/w/avra.toml", "/w/src/main.av"],
        ),
        "/w",
    )
    let _ = ws.items(ws.file_id("/w/src/main.av"))
    ws
}
fn cancel_decl(ws: Workspace, name: string) -> DeclId {
    [x.id for x in ws.decls.all_decls() if x.name == name][0]
}
/// Whether a call to `name` may park, asked of a fresh workspace.
fn parks(ws: Workspace, name: string) -> bool {
    let d = cancel_decl(ws, name)
    let _ = ws.cancel_bits_of(d)
    ws.decls.cancels_so_far(d)?.parks ?? false
}
fn cycle_source(leaf_body: string) -> string {
    "extern fn avra_fiber_sleep(ms: int)\nfn leaf() {\n    ${leaf_body}\n}\nfn ping(k: int) {\n    if k > 0 { pong(k - 1) } else { leaf() }\n}\nfn pong(k: int) {\n    if k > 0 { ping(k - 1) }\n}\nfn quiet() -> int { 1 }\n"
}
spec "compiler/cancel_reach — a fn's cancel bits settle with its own set (old path)" {
    given "a two-fn cycle whose way out reaches a fn that parks" {
        then "the fn that parks parks" {
            parks(cancel_workspace(cycle_source("avra_fiber_sleep(1)")), "leaf")
        }
        then "both members of the cycle park" {
            let ws = cancel_workspace(cycle_source("avra_fiber_sleep(1)"))
            parks(ws, "ping") && parks(ws, "pong")
        }
    }
    given "the same cycle where nothing parks" {
        then "neither member parks" {
            let ws = cancel_workspace(cycle_source("let _ = 1"))
            !parks(ws, "ping") && !parks(ws, "pong")
        }
    }
    given "a fn that calls nothing" {
        then "asking it settles none of the fns it does not call" {
            let ws = cancel_workspace(cycle_source("avra_fiber_sleep(1)"))
            let _ = parks(ws, "quiet")
            ws.db.value_hash_of(bits_key(cancel_decl(ws, "ping"))) == null
        }
    }
    given "a cycle asked from one member" {
        then "settles the whole set, and the fn it calls outside it" {
            let ws = cancel_workspace(cycle_source("avra_fiber_sleep(1)"))
            let _ = parks(ws, "pong")
            ws.db.value_hash_of(bits_key(cancel_decl(ws, "ping"))) != null &&
                ws.db.value_hash_of(bits_key(cancel_decl(ws, "leaf"))) != null
        }
    }
}
// A fn's written seats are settled with its strongly-connected set alone: a cycle takes what
// a member outside it writes, a cycle with no writer stays unwritten, and asking one fn
// settles no fn it does not call. `Writes` is family 41 by name; the keys are spelled
// through `family_ordinal`.
// The old path's cells, asked in an order; what a fn writes on the layer is writes_scc_test.av.
use @std.avrac.testing.old_path.{test_workspace}
use compiler.{Workspace}
use compiler.host.{memory_host}
use core.{DeclId}
use @std.relation.engine.{Key}
fn writes_key(d: DeclId) -> Key { Key { family: family_ordinal("Writes"), arg: d.index } }
fn writes_workspace(main: string) -> Workspace {
    let ws = test_workspace(
        memory_host(
            {
                "/w/avra.toml": "[package]\nname = \"app\"\nversion = \"0.1.0\"\n",
                "/w/src/main.av": main,
            },
            ["/w/avra.toml", "/w/src/main.av"],
        ),
        "/w",
    )
    let _ = ws.items(ws.file_id("/w/src/main.av"))
    ws
}
fn writes_decl(ws: Workspace, name: string) -> DeclId {
    [x.id for x in ws.decls.all_decls() if x.name == name][0]
}
fn written(ws: Workspace, name: string) -> bool {
    let d = writes_decl(ws, name)
    let _ = ws.writes_of(d)
    ws.decls.seat_written(d, 0)
}
fn cycle_source(leaf_body: string) -> string {
    "type P = { n: int }\nfn leaf(mut p: P) {\n    ${leaf_body}\n}\nfn ping(mut p: P, k: int) {\n    if k > 0 { pong(p, k - 1) } else { leaf(p) }\n}\nfn pong(mut p: P, k: int) {\n    if k > 0 { ping(p, k - 1) }\n}\nfn quiet(p: P) -> int { p.n }\n"
}
spec "compiler/receivers — a fn's written seats settle with its own set (old path)" {
    given "a two-fn cycle whose way out reaches a fn that writes" {
        then "the fn that writes writes the seat" {
            written(writes_workspace(cycle_source("p.n = 1")), "leaf")
        }
        then "a caller of it writes the seat" {
            let ws = writes_workspace(cycle_source("p.n = 1"))
            let _ = written(ws, "leaf")
            written(ws, "ping")
        }
        then "both members of the cycle write the seat" {
            let ws = writes_workspace(cycle_source("p.n = 1"))
            written(ws, "ping") && written(ws, "pong")
        }
    }
    given "the same cycle where nothing writes" {
        then "neither member writes it" {
            let ws = writes_workspace(cycle_source("let _ = p.n"))
            !written(ws, "ping") && !written(ws, "pong")
        }
    }
    given "a fn that calls nothing" {
        then "asking it settles none of the fns it does not call" {
            let ws = writes_workspace(cycle_source("p.n = 1"))
            let _ = written(ws, "quiet")
            ws.db.value_hash_of(writes_key(writes_decl(ws, "ping"))) == null
        }
    }
}
