fn cyclic() -> List<string> {
    [
        "type A = { b: B?, n: int }",
        "type B = { a: A?, c: C?, m: string }",
        "type C = { b: B?, a: A? }",
        "type D = { a: A, c: C, b: B }",
        "",
    ]
