// A top-level `state` is a place a body reads: a fn that reads one, directly
// or through a callee, is never constant, so it never hoists into the binary.
use @std.avrac.compiler.{analyze_source, Analysis}
use @std.avrac.core.{ExprId, StmtId, DeclId}
use @std.avrac.features.{SiteLowering}

fn body_of(a: Analysis, name: string) -> ExprId? {
    let s? = a
        .view
        .store
        .stmt_ids()
        .find(
            (k: StmtId) -> match a.view.store.stmt(k) {
                .FnDecl(n, _, _, _, _) -> n.of == name,
                rest -> false,
            },
        ) else {
        return null
    }
    match a.view.store.stmt(s) { .FnDecl(_, _, _, _, body) -> body, rest -> null }
}

fn decl_of(a: Analysis, name: string) -> DeclId {
    [x.id for x in a.view.decls.all_decls() if x.name == name][0]
}

fn hoists(l: SiteLowering) -> bool { match l { .Hoist -> true, rest -> false } }

spec "features/read_set — a top-level state is never constant" {
    given "a fn reading one directly" {
        then "its body does not hoist and the fn reads state" {
            let a = analyze_source("state n: int = 0\nfn f() -> int { n + 1 }")
            let body = body_of(a, "f")!
            !a.hoistable(body) &&
                !hoists(a.site_lowering(body)) &&
                a.decl_reads_state(decl_of(a, "f"))
        }
    }
    given "a caller of a fn reading one" {
        then "its body does not hoist either, and the caller reads state" {
            let a = analyze_source(
                "state n: int = 0\nfn g() -> int { n }\nfn f() -> int { g() + 1 }",
            )
            let body = body_of(a, "f")!
            !a.hoistable(body) &&
                !hoists(a.site_lowering(body)) &&
                a.decl_reads_state(decl_of(a, "f"))
        }
    }
    given "a fn reading no state" {
        then "it still hoists, so the witness separates the two" {
            let a = analyze_source("state n: int = 0\nfn f() -> int { 1 + 2 }")
            hoists(a.site_lowering(body_of(a, "f")!))
        }
    }
}
======
// avra-8sb5.57.9.7: `DocFact` is a `@side` partition over the same dense
// slot `Decls.faces` already uses — `decls.doc_facts` set beside
// `self.faced` (features/decls_mint.av), the one place a live parse's
// capture and a held record's `mint_faced` converge, so no declaration
// updates `DeclFacts` without `DocFact` agreeing. This is the witness for
// the column alone; the renderer still reads `doc_of`/`annotations_of`
// (decl_facts_test.av) until the second slice moves it inside the query.
use @std.avrac.compiler.{analyze_source, Analysis}
use @std.avrac.features.{DocFact, Decl, new_decls, DeclFacts, AnnotationFact, LitArg, LitKind}
use @std.avrac.core.{DeclId, FileId, DeclKind, no_stmt}

fn doc_fact_of(a: Analysis, name: string) -> DocFact? {
    let d = decl_named(a, name)
    DocFact.get(a.view.decls.doc_facts.get(), d.index)
}

spec "DocFact — a declaration's doc and annotations, as a @side column" {
    given "a documented, annotated fn" {
        then "its DocFact agrees with Decls.doc_of/annotations_of" {
            let a = analyze_source(
                "fn tag(s: string) { }\n/// line one\n/// line two\n@tag(\"x\")\nfn f() -> int {\n    1\n}\nf()",
            )
            let row = doc_fact_of(a, "f")!
            (row.doc ?? []).join("\n") == "line one\nline two" &&
                row.annotations.length == 1 &&
                row.annotations[0].name == "tag" &&
                [x.text for x in row.annotations[0].args].join(",") == "x"
        }
    }
    given "a plain fn with neither" {
        then "its DocFact reads the empty seed, not absent" {
            let a = analyze_source("fn f() -> int {\n    1\n}\nf()")
            let row = doc_fact_of(a, "f")!
            row.doc == null && row.annotations.is_empty()
        }
    }
    given "a held declaration, minted straight from a record" {
        then "its DocFact holds what it was minted with — the door a parsed one's facts land through" {
            mut decls = new_decls()
            let f: FileId = decls.file_id("/held/src/lib.av", "held:src/lib.av", "lib", false)
            let facts = DeclFacts {
                external: false,
                stat: true,
                is_grammar: false,
                is_component: false,
                span: null,
                tparams: [],
                bounds: [],
                seats: [],
                host: [],
                annotated: true,
                of: "",
                doc: ["a held const"],
                annotations: [
                    AnnotationFact {
                        name: "kept",
                        args: [LitArg { text: "x", kind: LitKind.Text }],
                        span: null,
                    },
                ],
            }
            let d: DeclId = decls
                .mint_faced(f, no_stmt, "K", DeclKind.Const, true, "", null, "", null, "", facts)
            let row = DocFact.get(decls.doc_facts.get(), d.index)!
            (row.doc ?? []).join("\n") == "a held const" &&
                row.annotations.length == 1 &&
                row.annotations[0].name == "kept"
        }
    }
}
