######## decl_rows
// A file's `Items` cell hashes its STABLE rows — name, kind, owner, visibility, parse
// facts — so a body, a comment or a reindent moves nothing, and a rename, a kind change, a
// moved annotation or a new declaration moves it. A reader of one foreign declaration
// records its NAME's bucket instead, never that whole file; the file's own minter, which
// reads its rows while they are made, never records itself. `a_process_over`, `checked`
// and `decl_in_file` are workspace_fixtures.av's own.
use compiler.{Workspace}
use @std.relation.engine.{Key}

fn items_ordinal() -> int { family_ordinal("Items") }

/// `b`'s `Items` cell as it settles over `text`, the only file that varies.
fn items_hash(text: string) -> int? {
    let files: Map<string, string> = {"/w/src/b.av": text}
    let ws = a_process_over(files, ["/w/src/b.av"])
    let b = ws.file_id("/w/src/b.av")
    let _ = ws.items(b)
    ws.db.value_hash_of(Key { family: items_ordinal(), arg: b.index })
}

fn base_b() -> string {
    "export fn helper(n: int) -> int {\n    n + 1\n}\nexport type Box = { v: int }\nexport type Other = { w: int }\nimpl Box {\n    fn get() -> int {\n        self.v\n    }\n}\nimpl Other {\n    fn peek() -> int {\n        self.w\n    }\n}\n"
}

/// `text` is the same row set as `base_b`.
fn same_rows(text: string) -> bool {
    let before = items_hash(base_b())
    before != null && before == items_hash(text)
}

/// `text` is another row set.
fn other_rows(text: string) -> bool {
    let before = items_hash(base_b())
    let after = items_hash(text)
    before != null && after != null && before != after
}

spec "compiler/rows — a file's items hash the stable rows" {
    then "fixture: the rows settle a hash" {
        items_hash(base_b()) != null
    }
    then "a body edit moves nothing" {
        same_rows(base_b().replace("n + 1", "n + 2"))
    }
    then "a comment moves nothing" {
        same_rows("// what helper does\n${base_b()}")
    }
    then "blank lines move nothing" {
        same_rows("\n\n${base_b()}")
    }
    then "a signature's TYPE moves nothing: the signature is Sig's" {
        same_rows(
            base_b().replace("(n: int) -> int", "(n: int) -> string").replace("n + 1", "\"s\""),
        )
    }
    then "a rename moves it" {
        other_rows(base_b().replace("helper", "helper2"))
    }
    then "visibility moves it" {
        other_rows(base_b().replace("export fn helper", "fn helper"))
    }
    then "a kind change moves it" {
        other_rows(
            base_b()
                .replace("export type Box = { v: int }", "export enum Box {\n    A\n}")
                .replace("self.v", "1"),
        )
    }
    then "a new declaration moves it" {
        other_rows("${base_b()}export fn extra() -> int {\n    3\n}\n")
    }
    then "a parameter NAME moves it: the seats are a fact of the row" {
        other_rows(base_b().replace("(n: int)", "(m: int)").replace("n + 1", "m + 1"))
    }
    then "swapping two methods between two impls moves it" {
        other_rows(
            base_b()
                .replace("fn get()", "fn tmp()")
                .replace("fn peek()", "fn get()")
                .replace("fn tmp()", "fn peek()"),
        )
    }
    then "declaration order moves it" {
        other_rows(
            base_b()
                .replace(
                    "export type Box = { v: int }\nexport type Other = { w: int }\n",
                    "export type Other = { w: int }\nexport type Box = { v: int }\n",
                ),
        )
    }
    then "a `///` doc line moves it" {
        other_rows(base_b().replace("export fn helper", "/// adds one\nexport fn helper"))
    }
}

/// `a`'s `g` calls `helper` from `b`.
fn caller_files() -> Map<string, string> {
    {"/w/src/a.av": "export fn g() -> int {\n    helper(1)\n}\n", "/w/src/b.av": base_b()}
}

/// Whether `key`'s cell lists a dep on the file's `Items`.
fn reads_items(ws: Workspace, frame: Key, file: string) -> bool {
    let f = ws.file_id(file)
    ws.db.edges_by_reader(frame).any((k: Key) -> k.family == items_ordinal() && k.arg == f.index)
}

/// Whether `frame`'s cell lists the dep a label names.
fn lists(ws: Workspace, frame: Key, label: string) -> bool {
    ws.db.edges_by_reader(frame).any((k: Key) -> ws.key_label(k) == label)
}

spec "compiler/rows — a foreign read records its name's bucket" {
    then "a caller's typing lists its callee's name, and neither the callee's file nor a name it never reads" {
        let names = ["/w/src/a.av", "/w/src/b.av"]
        let ws = a_process_over(caller_files(), names)
        let _ = checked(ws, "/w/src/a.av")
        let g = ws.typed_key(decl_in_file(ws, "/w/src/a.av", "g"))
        lists(ws, g, "Named(helper)") &&
            !reads_items(ws, g, "/w/src/b.av") &&
            !lists(ws, g, "Named(peek)")
    }
    then "no file's Items lists itself" {
        let names = ["/w/src/a.av", "/w/src/b.av"]
        let ws = a_process_over(caller_files(), names)
        let _ = checked(ws, "/w/src/a.av")
        let a = ws.file_id("/w/src/a.av")
        let b = ws.file_id("/w/src/b.av")
        !reads_items(ws, Key { family: items_ordinal(), arg: a.index }, "/w/src/a.av") &&
            !reads_items(ws, Key { family: items_ordinal(), arg: b.index }, "/w/src/b.av")
    }
}
######## build_mode
// ONE STORE PER TREE, AND THE MODE IS THE PRINT'S. An object is one target's code
// and a linked module one link's answer, so every word of a toolchain that moves
// either must move the compiler's PRINT — which the store's header carries and
// every durable key folds — never the store root, which is the tree's one.
use @std.avrac.compiler.{build_cache_root}
use compiler.{Workspace, Toolchain, VerdictRead}
use compiler.store.{store_at}

/// A wasm toolchain as the build command spells one, shrinking.
fn wasm_tools() -> Toolchain {
    Toolchain {
        opt: "-Oz",
        runtime: "rt.a",
        linker: "clang",
        tools: [],
        target: "wasm32-wasip1",
        wasm_opt: "wasm-opt",
    }
}

/// The host's own toolchain.
fn host_tools() -> Toolchain { Toolchain { opt: "-O1", runtime: "rt.a", linker: "clang", tools: [] } }

/// A workspace over `binary`, built for `tools`.
fn built_workspace(binary: string, tools: Toolchain) -> Workspace {
    let ws = print_workspace(binary)
    ws.built_for(tools)
    ws
}

spec "compiler/build — one store per tree, and the mode is the print's" {
    given "a workspace built for a wasm target" {
        then "the store root is the tree's one, whatever the target" {
            let bin = real_binary("mode-target", "one compiler")
            build_cache_root(built_workspace(bin, wasm_tools())) == build_cache_root(built_workspace(bin, host_tools()))
        }
        then "the print moves with the target" {
            let bin = real_binary("mode-target-id", "one compiler")
            built_workspace(bin, wasm_tools()).compiler_id() != built_workspace(bin, host_tools()).compiler_id()
        }
        then "its restart reads the same store root" {
            let ws = built_workspace(real_binary("mode-anew", "one compiler"), wasm_tools())
            build_cache_root(ws.anew()) == build_cache_root(ws)
        }
        then "its restart's restart reads the same store root" {
            let ws = built_workspace(real_binary("mode-anew2", "one compiler"), wasm_tools())
            build_cache_root(ws.anew().anew()) == build_cache_root(ws)
        }
        then "its restart reads a binary's compiler as it does" {
            let ws = built_workspace(real_binary("mode-anew-key", "one compiler"), wasm_tools())
            ws.anew().read_now(VerdictRead.Compiler) == ws.read_now(VerdictRead.Compiler)
        }
        then "a binary's compiler read is not the host build's" {
            let bin = real_binary("mode-key", "one compiler")
            built_workspace(bin, wasm_tools()).read_now(VerdictRead.Compiler) != built_workspace(bin, host_tools()).read_now(VerdictRead.Compiler)
        }
        then "one code's OBJECT key is not the host build's — a host .o never answers a wasm link" {
            let bin = real_binary("mode-okey", "one compiler")
            built_workspace(bin, wasm_tools()).object_key_of("code") != built_workspace(bin, host_tools()).object_key_of("code")
        }
    }
    given "a workspace whose print and store root were asked before it was built for a target" {
        then "the store root does not move — the tree's is the tree's" {
            let bin = real_binary("mode-late", "one compiler")
            let ws = print_workspace(bin)
            let host_root = build_cache_root(ws)
            ws.built_for(wasm_tools())
            build_cache_root(ws) == host_root
        }
        then "the print moves with it" {
            let ws = print_workspace(real_binary("mode-late-id", "one compiler"))
            let host_id = ws.compiler_id()
            ws.built_for(wasm_tools())
            ws.compiler_id() != host_id
        }
        then "built for the host again, the print is the host's again" {
            let bin = real_binary("mode-back", "one compiler")
            let ws = built_workspace(bin, wasm_tools())
            let wasm_id = ws.compiler_id()
            ws.built_for(host_tools())
            ws.compiler_id() != wasm_id
        }
    }
    given "two wasm toolchains one word apart" {
        then "another target spelling is another print" {
            let bin = real_binary("mode-spelling", "one compiler")
            built_workspace(bin, wasm_tools()).compiler_id() != built_workspace(bin, wasm_tools() with { target: "wasm32-unknown-wasi" }).compiler_id()
        }
        then "a reactor is another print" {
            let bin = real_binary("mode-reactor", "one compiler")
            built_workspace(bin, wasm_tools()).compiler_id() != built_workspace(bin, wasm_tools() with { reactor: true }).compiler_id()
        }
        then "an unshrunk module is another print" {
            let bin = real_binary("mode-opt", "one compiler")
            built_workspace(bin, wasm_tools()).compiler_id() != built_workspace(bin, wasm_tools() with { wasm_opt: "" }).compiler_id()
        }
        then "a debug link is another print" {
            let bin = real_binary("mode-debug", "one compiler")
            built_workspace(bin, wasm_tools()).compiler_id() != built_workspace(bin, wasm_tools() with { debug: true }).compiler_id()
        }
        then "a reactor and a debug link are not one print" {
            let bin = real_binary("mode-marks", "one compiler")
            built_workspace(bin, wasm_tools() with { reactor: true }).compiler_id() != built_workspace(bin, wasm_tools() with { debug: true }).compiler_id()
        }
    }
    given "a workspace built for the host" {
        then "its print is the one a workspace nobody built carries" {
            let bin = real_binary("mode-host", "one compiler")
            built_workspace(bin, host_tools()).compiler_id() == print_workspace(bin).compiler_id()
        }
        then "a wasm-only word moves nothing on the host" {
            let bin = real_binary("mode-host-words", "one compiler")
            built_workspace(bin, host_tools()).compiler_id() == built_workspace(
                bin,
                host_tools() with { reactor: true, debug: true, wasm_opt: "wasm-opt" },
            )
                .compiler_id()
        }
    }
}
