######## direct_test_workspace
//! `compiler.direct_test_workspace`: a workspace a test makes through
//! `new_workspace` is refused; the same call outside a test stands.
use @std.avrac.testing.held.{held_at}

const MAKERS = "fn avra() -> int { 0 }\nfn new_workspace(host: int, root: string, lang: int) -> int { host + lang + root.length }\n"

/// Findings of the rule over one file at `rel` under `/w/src`.
fn made_at(rel: string, body: string) -> int {
    let path = "/w/src/${rel}"
    let ws = held_at({"${path}": "${MAKERS}${body}"}, "/w")
    [f for f in ws.judged_at(path).findings() if f.rule == "compiler.direct_test_workspace"].length
}

fn made() -> string { "fn f() -> int { new_workspace(1, \"/w\", avra()) }\n" }

spec "compiler/idioms (direct_test_workspace)" {
    given "a workspace made through `new_workspace`" {
        then "in a test file, it is refused" { made_at("tests/x_test.av", made()) == 1 }
        then "in a test directory's helper file, it is refused" { made_at("a/tests/fixtures.av", made()) == 1 }
        then "outside a test, it stands" { made_at("a/x.av", made()) == 0 }
    }
}
######## file_module_relation
// THE PARITY KEEPER: `File`/`Module` carry the real shape — the hand
// tables they replaced are gone, so what remains pins the two edges a
// relation-backed table can still get wrong: a bucket read before the
// row that belongs in it exists, and a row inserted after the pinned
// handle was taken.
use core.{FileId, same_file}
use compiler.{Workspace}
use features.{Decls, new_decls}

spec "compiler/file_rows — a module's file bucket read then written in one revision" {
    then "a file minted after its module's file list was read still reads back through the relation" {
        let ws = a_process_over(package_files(), ["/w/src/a.av"])
        let a_id = ws.file_id("/w/src/a.av")
        let m = ws.decls.file(a_id).module_id
        let before = ws.decls.files_of_module(m)
        let b_id = ws.file_id("/w/src/b.av")
        let after = ws.decls.files_of_module(m)
        before.length == 1 && after.length == 2 && after.any((f: FileId) -> same_file(f, b_id))
    }
}

// THE PINNED HANDLE'S IDENTITY: `Decls.file_rows`/`module_rows` are read once
// at construction (`Cell.new(File.rows_in(db))`) and never re-pinned — so a row
// a later `file_id`/`module_id` call inserts must still be visible through that
// SAME pin, or `file(f)`/`module_name(m)` would answer for a row that was never
// there when they were taken. Both read through the pin (`file`, `module_name`),
// proving it directly rather than through the index doors (`by_path`/`by_name`).
spec "compiler/file_rows — the pinned Rows<File>/Rows<Module> handle sees a row inserted after Decls was built" {
    then "a file minted after Decls was constructed reads back through the pin" {
        let d: Decls = new_decls()
        let f = d.file_id("/w/src/pinned.av", "w:src/pinned.av", "pinned", false)
        d.file(f).path == "/w/src/pinned.av"
    }
    then "a module minted after Decls was constructed reads back through the pin" {
        let d: Decls = new_decls()
        let f = d.file_id("/w/src/pinned.av", "w:src/pinned.av", "pinned", false)
        d.module_name(d.file(f).module_id) == "pinned"
    }
}
######## typed_window
// A body's typed facts stand over the declaration's window as it is now: a table restored under
// a scope made before the range was placed would start at the default, not at the body.
use compiler.{Workspace}
use core.{DeclId}

fn window_source() -> string { "fn a() -> int {\n    1\n}\nfn b() -> int {\n    let x = 2\n    x\n}\n" }

fn body_named(ws: Workspace, name: string) -> DeclId {
    [x.id for x in ws.decls.all_decls() if x.name == name][0]
}

spec "compiler/typed_body — a body's tables start where its declaration does" {
    given "a file of two bodies, checked" {
        then "the second body's expression window starts at its declaration's first expression" {
            let ws = a_process_over({"/w/src/main.av": window_source()}, ["/w/src/main.av"])
            let _ = checked(ws, "/w/src/main.av")
            let b = body_named(ws, "b")
            ws.typed(b).of_expr.lo() == ws.decls.decl(b).lo
        }
        then "the second body's statement window starts at its declaration's first statement" {
            let ws = a_process_over({"/w/src/main.av": window_source()}, ["/w/src/main.av"])
            let _ = checked(ws, "/w/src/main.av")
            let b = body_named(ws, "b")
            ws.typed(b).stmt_flags.lo() == ws.decls.decl(b).stmt_lo
        }
    }
}
