fn unread_homes(engine: QueryEngine, n: Node) -> List<string> {
    match n {
        .Template(home, _, _, fills) -> if home_read(engine, home) { [] } else { [home] }
            .concat(flatten([unread_homes(engine, f) for f in fills])),
        .Interp(_, holes) -> flatten([unread_homes(engine, h) for h in holes]),
        .Many(items) -> flatten([unread_homes(engine, i) for i in items]),
        .Name(_) or .Text(_) or .Int(_) or .Float(_) or .Bool(_) -> [],
    }
}

/// Whether the file `home` names is one this program reads: a source of the package it names.
fn home_read(engine: QueryEngine, home: string) -> bool {
    let at? = template_file(home) else { return false }
    package_sources(engine, at.package_name, "src").contains(at.path_in_package)
}

/// Each file a template among `n` and the nodes it holds names whose text did not parse.
fn unparsed_homes(engine: QueryEngine, n: Node) -> List<string> {
    match n {
        .Template(home, _, _, fills) -> if home_unparsed(engine, home) { [home] } else { [] }
            .concat(flatten([unparsed_homes(engine, f) for f in fills])),
        .Interp(_, holes) -> flatten([unparsed_homes(engine, h) for h in holes]),
        .Many(items) -> flatten([unparsed_homes(engine, i) for i in items]),
        .Name(_) or .Text(_) or .Int(_) or .Float(_) or .Bool(_) -> [],
    }
}

/// Whether an item of the file `home` names did not parse: what a template there writes is missing
/// what the parse refused.
fn home_unparsed(engine: QueryEngine, home: string) -> bool {
    let f? = template_file(home) else { return false }
    item_ids(engine, f).any((i: int) -> !read_item(engine, f, i).store.refusals().is_empty())
}

