cd /work/avra-i4/packages/std-avrac/src/features/quote/tests; head -12 quote_test.av; cat > template_judged_test.av <<'EOF'
// A TEMPLATE IS JUDGED WHERE IT IS WRITTEN: a refusal inside a generator's template is its author's,
// said once, in the check of the package that wrote it, and never again in each program that
// splices it. Its holes are what the instance decides: nothing a fill could change is said here.
use @std.avrac.testing.{judged, provided, refused_in, refusals}

/// A provider writing one template, inside a trait's `derive`: `body` is what the quote holds.
fn deriving(body: string) -> string {
    "use @std.meta.{Type, Directive}\nfn shout(s: string) -> string { \"${s}!\" }\nexport trait Made {\n    static fn derive(t: Type) -> List<Directive> {\n        [Directive { twin: \"\", name: t.name, at: t.at, source: quote { ${body} } }]\n    }\n}\n0"
}

/// A program deriving the provider's trait over one record, then calling `call`.
fn deriving_program(call: string) -> string { "use @std.meta.{derive}\nuse @x.c.{Made}\n@derive(Made)\ntype P = { x: int }\n${call}" }

spec "features/quote — a template is judged where it is written" {
    given "the package that writes a template" {
        then "a body answering against its declaration is refused at the template, once" {
            let p = judged(deriving("fn gone() -> int { \"no\" }"))
            refused_in(p, "the body answers `string` but `gone` declares `int`") && p.report().contains("main.av:5:")
        }
        then "a call in a method over a hole's type is refused at the call" {
            refused_in(
                judged(deriving("impl \${t} { fn loud() -> string { shout(1) } }")),
                "argument 1 of `shout` wants `string`, found `int`",
            )
        }
        then "a hole standing for a type, a name and a value says nothing of its own" {
            refusals(deriving("fn \${t}_twice(v: \${t}) -> \${t} { v }")) == 0
        }
    }
    given "a program splicing another package's template" {
        then "hears the template's refusal once, where the template is written" {
            let p = provided(deriving_program("0"), deriving("fn gone() -> int { \"no\" }"))
            refused_in(p, "the body answers `string` but `gone` declares `int`") && p.report().contains("vendor/c/src/")
        }
    }
}
EOF
