new='''/// Where the generated item `at` stands among its file's generated items, counted from zero; absent
/// for a written item's id, and for a quoted one's.
export fn generated_rank(at: int) -> int? { if at < GENERATED_FIRST || at >= QUOTED_FIRST { null } else { at - GENERATED_FIRST } }

/// Where the ids of a file's quoted items start — its templates opened where they are written
/// (`file_quoted`): past every generated item's.
export const QUOTED_FIRST: int = 2199023255552

/// The id of a file's `k`-th quoted item, counted from zero in the order its quotes are written.
export fn quoted_id(k: int) -> int { QUOTED_FIRST + k }

/// Where the quoted item `at` stands among its file's quoted items, counted from zero; absent for
/// any other id.
export fn quoted_rank(at: int) -> int? { if at < QUOTED_FIRST { null } else { at - QUOTED_FIRST } }'''
assert s.count(old)==1; s=s.replace(old,new); open(p,'w').write(s)

