old='''export fn generated_at(engine: QueryEngine, file: SourceFileAddress, at: int) -> GeneratedItem? {
    let k? = generated_rank(at) else { return null }'''
new='''export fn generated_at(engine: QueryEngine, file: SourceFileAddress, at: int) -> GeneratedItem? {
    let q = quoted_rank(at)
    if q != null {
        let quoted = file_quoted(engine, file).items
        return if q! < quoted.length { quoted[q!].item } else { null }
    }
    let k? = generated_rank(at) else { return null }'''
assert s.count(old)==1; s=s.replace(old,new)
old='''/// Whether `file` holds the item `at`, written or made by its generators'''
new='''/// Every item of `file` its laws judge, by id: every item, then each of its templates opened where
/// it is written (`file_quoted`).
export fn judged_item_ids(engine: QueryEngine, file: SourceFileAddress) -> List<int> {
    every_item_id(engine, file).concat([quoted_id(k) for k in 0..file_quoted(engine, file).items.length])
}

/// THE TEMPLATES A FILE WRITES, OPENED WHERE THEY ARE WRITTEN: each quote of its written items that
/// declares something, copied as a generator's splice copies it, every hole filled by a placeholder
/// no program can write, as an item of its own that no file declares and nothing runs. A refusal
/// inside a template is its author's, so it is said once, in the check of the package that wrote
/// it, never again in each program that splices it; what a hole's fill decides stays the instance's
/// (`QuotedItem.holes`).
@cut_query
export fn file_quoted(engine: QueryEngine, file: SourceFileAddress) -> QuotedItems {
    QuotedItems { items: flatten([item_quotes(engine, file, i) for i in item_ids(engine, file)]) }
}

/// A file's templates opened where they are written, in the order written.
@derive(Saved)
export type QuotedItems = { items: List<QuotedItem> }

/// A template opened where it is written: its copy as an item, and where each of its holes stands in
/// its file, as a low and a high offset in turn — a finding standing on a hole, or holding one,
/// depends on what fills it, and is the instance's to say.
@derive(Saved)
export type QuotedItem = { item: GeneratedItem, holes: List<int> }

/// The placeholder every hole of an opened template is filled by: a name no program can write, so
/// nothing reads or declares it but the copy.
const QUOTE_HOLE: string = "$hole"

/// Each declaring template the written item `at` of `file` holds, outermost, opened.
fn item_quotes(engine: QueryEngine, file: SourceFileAddress, at: int) -> List<QuotedItem> {
    let store = read_item(engine, file, at).store
    let start = item_start(engine, file, at)
    let quotes = [e for j in 0..store.expr_count() for e in [ExprId { index: j }] if store.expr(e).body_of()?.word == "quote" && store.expr_span(e) != null]
    let outer = [q for q in quotes if !quotes.any((o) -> o.index != q.index && within(store.expr_span(q)!, store.expr_span(o)!))]
    flatten([quote_opened(engine, file, store, start, q) for q in outer if quote_kind(store, q) is .Decls])
}

/// Whether `inner` stands within `outer`.
fn within(inner: Span, outer: Span) -> bool { outer.lo <= inner.lo && inner.hi <= outer.hi }

/// The template `q`, of an item of `file` whose store is `store` and whose text starts at `start`,
/// copied with every hole filled by the placeholder; none where the copy makes no item.
fn quote_opened(engine: QueryEngine, file: SourceFileAddress, store: SyntaxArena, start: int, q: ExprId) -> List<QuotedItem> {
    let bp? = store.expr(q).body_of() else { return [] }
    let at = start + store.expr_span(q)!.lo
    let node = Node.Template(template_home(file), at, bp.parts, [Node.Name(QUOTE_HOLE) for h in bp.holes])
    let made = items_spliced(engine, file, "", [Directive { twin: "", name: "", at: null, source: MetaDecls { node: node } }])
    let holes = flatten([[start + sp.lo - 2, start + sp.hi + 1] for h in bp.holes for sp in some_list(store.expr_span(h))])
    [QuotedItem { item: g, holes: holes } for g in made.items]
}

/// Whether `file` holds the item `at`, written or made by its generators'''
