42	export fn quote_type(mut cx: TypeCx, e: ExprId) -> TypeId {
43	    let q? = cx.view.store.expr(e).body_of() else { return cx.error_type }
44	    // a body that did not parse has spoken already
45	    let stmts: List<StmtId> = match q.view { .Verbatim(ss, _) -> ss, rest -> [] }
46	    if stmts.any((s: StmtId) -> cx.view.store.stmt(s) is .Error) { return cx.error_type }
47	    // a hole whose own value refused has spoken already
48	    if q.holes.any((h: ExprId) -> cx.errored(h)) { return cx.error_type }
49	    let classes = [class_of(cx.view.decls, cx.type_at(h), cx.shape_at(h)) for h in q.holes]
50	    let whole = quote_kind(cx.view.store, e)
51	    let kinds = hole_kinds(cx.view.store, e)
52	    // a value no seat takes refuses in its seat's words where the
53	    // seat is known; a body of holes has no seat until its kind is
54	    for k, h in q.holes {
55	        if classes[k] == null {
56	            let at = cx.loc_of(h)
57	            let found = cx.name_at(h)
58	            return cx
59	                .spoken(
60	                    if whole is .Holes { unfillable(at, found) } else { hole_refused(at, kinds[k], found) },
61	                )
62	        }
63	    }
64	    let fills = [c! for c in classes]
65	    let rewrites = fills.any(fills_by_node(it))
66	    let answered: MetaKind? = match whole {
67	        .Expr -> if rewrites { MetaKind.Rewrite } else { expression_kind(cx, e) },
68	        .Stmts -> if rewrites { MetaKind.Rewrite } else { MetaKind.Stmts },
69	        .Arms -> MetaKind.Arms,
70	        .Decls -> MetaKind.Decls,
71	        .Holes -> holes_kind(fills),
72	    }
73	    if answered == null { return cx.spoken(mixed_holes(cx.loc_of(e))) }
74	    let answer = answered!
75	    for k, h in q.holes {
76	        let kind = if whole is .Holes { holes_seat(answer, q.holes.length) } else { kinds[k] }
77	        let class = fills[k]
78	        if class is .Text && (kind is .Expression || kind is .Tail) { return cx.spoken(ambiguous_text(cx.loc_of(h))) }
79	        if answer == MetaKind.Rewrite && !rewrite_takes(class) { return cx.spoken(rewrite_hole(cx.loc_of(h), cx.name_at(h))) }
80	        if !fits(class, kind) { return cx.spoken(hole_refused(cx.loc_of(h), kind, cx.name_at(h))) }
81	    }
82	    let d? = cx.view.decls.meta_named(meta_name(answer)) else { return cx.spoken(no_meta(cx.loc_of(e), meta_name(answer))) }
83	    cx.view.decls.self_type_of(d)
