64	/// what it stands under, `at` under `parent`.
65	fn walk_under(store: SyntaxArena, at: At, parent: At?, quoted: bool, walked: Cell<List<WalkedNode>>) {
66	    let kind = store.node_kind(at)
67	    let here = WalkedNode {
68	        at: at,
69	        kind: kind,
70	        quoted: quoted || is_quote(store, at, kind),
71	        under: parent,
