77	/// The nodes `walked`, filed by kind in the order they come, each with its place among them.
78	fn kinds_filed(walked: List<WalkedNode>) -> List<KindNodes> {
79	    mut filed: List<KindNodes> = []
80	    for place, r in walked {
81	        let k? = r.kind else { continue }
82	        let node = Walked { at: r.at, place: place, quoted: r.quoted }
83	        let held? = filed.find(it.kind == k) else {
84	            filed = filed.concat([KindNodes { kind: k, nodes: Cell.new([node]) }])
85	            continue
86	        }
87	        held.nodes.push(node)
88	    }
89	    filed
