114	    /// The nodes of any of the kinds `on` that `reach` reaches in the item, in the order it reaches
115	    /// them; those a quote writes only where `quotes`.
116	    fn nodes_on(on: List<NodeKind>, reach: Reach, quotes: bool) -> List<At> {
117	        let filed = match reach {
118	            .Walked -> self.walked().kinds,
119	            .Stored -> self.stored.get() ?? self.held_stored(),
120	            .Typed -> self.typed_kinds.get() ?? self.held_typed(),
