128	    /// the node whose kids it is; absent for a top-level statement.
129	    fn under(at: At) -> At? {
130	        let walk = self.walked()
131	        match at {
132	            .Expr(e) -> walk.exprs.at(e.index),
133	            .Stmt(s) -> walk.stmts.at(s.index),
134	            .Pat(p) -> walk.pats.at(p.index),
135	            .Field(owner, _) -> At.Expr(owner),
136	            .Param(owner, _) -> At.Stmt(owner),
137	        }
