258	    let own_path = template_home(file)
259	    let place? = f.at else { return f with { named: null, fixes: [], aside: null, item: null } }
260	    let wrote? = writer_at(store, place, own_path) else { return f with { at: null, named: null, fixes: [], aside: null, item: null } }
261	    let named = if writer_at(store, f.named ?? place, own_path)?.path == wrote.path { f.named } else { null }
