796	            .Names(ts) -> self.dst.alloc_pat(Pat.Bind(Scoped(ts.first() ?? ""))),
797	            .Type(t) -> self.dst.alloc_pat(Pat.Bind(Scoped(t.name))),
798	            .Unplaceable(why) -> self.dst.alloc_pat(Pat.Bind(Scoped(self.unplaced_name(k, why)))),
