50	/// One template's parse: the store that holds it and the quote it was
51	/// written in.
52	export type Scratch = {
53	    store: SyntaxArena,
54	    body: ExprId,
55	    /// Where the store's places count from in the file the quote is written in: its item's start, for
56	    /// a quote read where it was written; none for one parsed from its parts.
57	    start: int? = null,
58	}
