60	/// Where a template was written, as a splice finds it: the parse of the quote the file a home names
61	/// holds at an offset, its own nodes; absent where that file is out of sight.
62	export alias WrittenAt = fn(string, int) -> Scratch?
63	
64	/// A splice that reaches no file a template was written in.
65	fn nothing_written() -> WrittenAt { (_home: string, _at: int) -> null }
