69	/// The door a language opens for the sugars of the stores it parses.
70	export fn sugar_door(lang: Language) -> Means {
71	    (store: SyntaxArena, sugar: ExprId) -> minted_means(lang, store, sugar)
72	}
73	
74	/// What the sugar means, copied beside it: the nodes the copy minted, the
75	/// last the root; none when the node is no sugar or its template cannot be
76	/// read here.
77	fn minted_means(lang: Language, store: SyntaxArena, sugar: ExprId) -> Result<Minting, string> {
78	    let node = store.expr(sugar)
79	    if !sugared(node) { return .Ok(minting([])) }
80	    let cx = MeanCx {
81	        store: store,
82	        at: sugar,
83	        span: store.expr_span(sugar),
84	        provided: store.provided_of(sugar),
85	        door: sugar_door(lang),
86	    }
87	    let said? = node.means(cx) else { return node.minted(cx) }
88	    .Ok(minting(rewritten_beside(lang, store, sugar, said?)))
89	}
