91	/// Whether `e` is of a kind that means something: one whose `Meaning` writes what it means, or what
92	/// it mints. Every kind is spelled, so a kind added is placed here.
93	fn sugared(e: Expr) -> bool {
94	    match e {
95	        .ArmsBody or .Bitnot or .BlockLambda or .BracedHead or .ChainApply or .ChainCall or .ChainType or .Component or .GrammarLit or .If or .InstanceFn or .LetPattern or .Neg or .Pipe or .Table or .Trailed or .TypeLiteral -> true,
96	        .Binary or .Block or .Body or .BoolLit or .BytesLit or .Call or .CallValue or .Catch or .Chain or .Channel or .Coalesce or .Collect or .Comp or .CtxRead or .ElseArm or .Emit or .Env or .Error or .FloatLit or .Force or .Ident or .Index or .IntLit or .Is or .Lambda or .ListLit or .MapLit or .Match or .MatchOpt or .MethodCall or .Named or .Not or .NullLit or .Produce or .Prop or .Propagate or .Range or .Receiver or .Select or .Spawn or .StrLit or .StructLit or .VariantLit or .WaitArm or .When or .With or .Within -> false,
97	    }
98	}
