100	/// A rewrite's template copied beside `sugar` with its holes filled and the names it binds made fresh, so
101	/// none captures or is captured by a name of the code it lands in: the nodes made, the root last;
102	/// none when the template can't be read here.
103	export fn rewritten_beside(lang: Language, store: SyntaxArena, sugar: ExprId, said: Rewrite) -> List<
104	    ExprId,
105	> {
106	    let copy? = copied_template(lang, store, said, "·e${sugar.index}") else { return [] }
107	    let last? = copy.stmts.last() else { return [] }
108	    let root? = store.answer_of(last) else { return [] }
109	    let at = store.expr_span(sugar)
110	    if at != null { for m in copy.exprs { store.place_expr(m, at!) } }
111	    copy.exprs.filter(!same_expr(it, root)).concat([root])
112	}
