114	/// A rewrite's statements copied in place of the statement `sugar`, holes filled and its own names
115	/// made fresh: the statements made, in order; none when the template can't be read here.
116	export fn stmts_rewritten_beside(lang: Language, store: SyntaxArena, sugar: StmtId, said: Rewrite) -> List<
117	    StmtId,
118	> {
119	    copied_template(lang, store, said, "·s${sugar.index}")?.stmts ?? []
120	}
