122	/// A template copied into `store`: what it is in the seat it fills (statements and arms, a field
123	/// run's fields, or a record literal's fields), every expression the copy made, and the words for
124	/// each fill it couldn't place.
125	type TemplateCopy = {
126	    stmts: List<StmtId>,
127	    exprs: List<ExprId> = [],
128	    arms: List<Arm> = [],
129	    params: List<Param> = [],
130	    inits: Inits = no_inits(),
131	    refused: List<string> = [],
132	    binders: List<PatId> = [],
133	    /// Whether the copy's own nodes stand where its template was written, in that file's places.
134	    placed: bool = false,
135	}
