137	/// A rewrite's template copied into `store`, holes filled and the names it binds marked `fresh`; absent
138	/// when it is no template, or can't be read here.
139	fn copied_template(lang: Language, store: SyntaxArena, said: Rewrite, fresh: string) -> TemplateCopy? {
140	    let refused: Cell<List<string>> = Cell.new([])
141	    let sp = Splice {
142	        lang: lang,
143	        store: store,
144	        refused: refused,
145	        unplaced: list_cell(),
146	        spliced: map_cell(),
147	        binders: list_cell(),
148	        written: nothing_written(),
149	        of: SpliceOf.Meaning,
150	        fresh: fresh,
151	    }
152	    match said.node {
153	        .Template(file, at, parts, fills) -> sp.copied(file, at, parts, fills, HoleKind.Statement),
154	        .Name(_) or .Text(_) or .Int(_) or .Float(_) or .Bool(_) or .Interp(_, _) or .Many(_) -> null,
155	    }
156	}
157	
158	/// The template's runs with a hole between each, as the quote it was
159	/// written in.
160	fn woven_quote(parts: List<string>) -> string {
161	    let holed = [p + "\${0}" for p in parts.slice(0, parts.length - 1)].join("")
162	    "quote { ${holed}${parts.last()!} }"
163	}
164	
165	/// THE ONE SPLICE DOOR: a template's runs, parsed once, copied into `store` as the seat `seat` takes
166	/// it, each hole filled by `fills` at its own seat; the names it binds marked `fresh`, and each node it
167	/// made marked as written at `origin`, where the names it reads and never binds resolve. Absent when the runs aren't a quote.
168	fn template_copied(
169	    lang: Language,
170	    store: SyntaxArena,
171	    written: Scratch?,
172	    parts: List<string>,
173	    fills: List<fn(HoleKind) -> Filled>,
174	    seat: HoleKind,
175	    fresh: string?,
176	    origin: ForeignOrigin,
177	) -> TemplateCopy? {
178	    let s? = written ?? scratch(lang, woven_quote(parts)) else { return null }
179	    let body? = s.store.expr(s.body).body_of() else { return null }
180	    let stmts: List<StmtId> = match body.view {
181	        .Verbatim(ss, _) -> ss,
182	        .None or .Expanded(_) -> [],
183	    }
184	    let arms: List<Arm> = match body.view {
185	        .Verbatim(_, written) -> written,
186	        .None or .Expanded(_) -> [],
187	    }
188	    mut rb = copier(s.store, store, fills, hole_runs(s.store, s.body), sugar_door(lang)) with { fresh: fresh, binds: if fresh == null { [] } else { template_binds(s.store, stmts, arms) } }
189	    let copy = seated_copy(s.store, stmts, arms, seat, origin.path, rb)
190	    store.note_kept_origins(rb.made_exprs, rb.made_from, s.store)
191	    store.note_made(rb.made_nodes(), origin)
192	    let start = if origin.spanned_home { s.start } else { null }
193	    if start != null { store.moved_on(rb.made_exprs, rb.made_stmts, rb.made_pats, rb.made_params, start!) }
194	    copy with { placed: start != null, exprs: if start != null { rb.holed_exprs } else { flatten([rb.made_exprs, rb.holed_exprs]) }, binders: rb.holed_pats.concat(rb.filled_pats), refused: copy
195	        .refused
196	        .concat(["hole ${k}'s fill doesn't fit its seat" for k in rb.misfits])
197	        .concat([u.why for u in rb.unplaceable]) }
198	}
