200	/// Every name a template binds, under its statements and arms: a `let`'s, a pattern's, a fn's or a
201	/// lambda's seat.
202	fn template_binds(store: SyntaxArena, stmts: List<StmtId>, arms: List<Arm>) -> List<string> {
203	    let armed = flatten(
204	        [[At.Pat(p) for p in a.pats]
205	            .concat([At.Expr(g!) for g in [a.guard] if g != null])
206	            .concat([At.Expr(a.value)]) for a in arms],
207	    )
208	    flatten(
209	        [bound_at(store, at) for root in [At.Stmt(s) for s in stmts].concat(armed) for at in under(store, root)],
210	    )
211	}
212	
213	/// `at` and every node under it.
214	fn under(store: SyntaxArena, at: At) -> List<At> { [at].concat(flatten([under(store, k) for k in store.kids_walked(at)])) }
215	
216	/// The names one node binds.
217	fn bound_at(store: SyntaxArena, at: At) -> List<string> {
218	    match at {
219	        .Stmt(s) -> [n! for n in [store.let_name(s)] if n != null]
220	            .concat([p.name.of for p in store.fn_parts(s)?.params ?? []]),
221	        .Pat(p) -> [b.name for b in store.pattern_binds(p)],
222	        .Expr(e) -> [p.name.of for p in store.lambda_parts(e)?.params ?? []],
223	        .Field(_, _) or .Param(_, _) -> [],
224	    }
225	}
