227	/// A template's body copied as its seat takes it: a field run its declarations' fields, a record
228	/// literal's fields its literal's, any other seat its statements and arms.
229	fn seated_copy(
230	    src: SyntaxArena,
231	    stmts: List<StmtId>,
232	    arms: List<Arm>,
233	    seat: HoleKind,
234	    written_in: string,
235	    mut rb: Rebuilder,
236	) -> TemplateCopy {
237	    match seat {
238	        .Fields -> {
239	            let fields = [fields_of(src.stmt(s)) for s in stmts]
240	            let params = rb.params(flatten([f ?? [] for f in fields]))
241	            TemplateCopy {
242	                stmts: [],
243	                params: params,
244	                refused: if fields.any(it == null) { [no_fields(written_in)] } else { [] },
245	            }
246	        },
247	        .Inits -> {
248	            let inits? = literal_inits(src, stmts, rb) else {
249	                return TemplateCopy {
250	                    stmts: [],
251	                    inits: spoiled_inits(),
252	                    refused: [no_literal(written_in)],
253	                }
254	            }
255	            TemplateCopy { stmts: [], inits: inits }
256	        },
257	        .Expression or .Name or .Binder or .Type or .Statement or .Arm or .Run or .Tail -> {
258	            let copied = rb.stmts(stmts)
259	            TemplateCopy { stmts: copied, arms: rb.arms(arms) }
260	        },
261	    }
262	}
