264	/// The fields of the record literal a template's last statement answers, copied; absent when it
265	/// answers none.
266	fn literal_inits(src: SyntaxArena, stmts: List<StmtId>, mut rb: Rebuilder) -> Inits? {
267	    let last? = stmts.last() else { return null }
268	    let e? = src.answer_of(last) else { return null }
269	    match src.expr(e) { .StructLit(_, names, values) -> rb.inits(names, values), rest -> null }
270	}
