272	/// Whether a template's runs are nothing but holes: its kind is then whatever fills them.
273	fn bare_template(lang: Language, parts: List<string>) -> bool {
274	    let s? = scratch(lang, woven_quote(parts)) else { return false }
275	    match quote_kind(s.store, s.body) {
276	        .Holes -> true,
277	        .Expr or .Stmts or .Arms or .Decls -> false,
278	    }
279	}
