281	/// A node of the store a meaning rewrites, in the seat its hole stands in: an id, as the seat reads
282	/// it; a name, as written; a held node, where a node of its arena stands; a run of held nodes, where
283	/// statements or a run stand. Absent for a fill that holds no node — a template a helper built,
284	/// which is copied in its turn.
285	fn node_filled(kind: HoleKind, fill: Node) -> Filled? {
286	    match fill {
287	        .Int(index) -> id_filled(kind, index),
288	        .Name(text) -> Filled.Name(text),
289	        .Many([.Name(arena), .Int(index)]) -> held_filled(kind, arena, index),
290	        .Many(items) -> if items.all(held_at(it) != null) { run_filled(kind, items) } else { null },
291	        .Template(_, _, _, _) or .Text(_) or .Float(_) or .Bool(_) or .Interp(_, _) -> null,
292	    }
293	}
