295	/// An id in the seat it stands in: an expression or a pattern.
296	fn id_filled(kind: HoleKind, index: int) -> Filled {
297	    match kind {
298	        .Expression or .Tail -> Filled.Expr(ExprId { index: index }),
299	        .Binder -> Filled.Pat(PatId { index: index }),
300	        rest -> Filled.Unplaceable("a rewrite's hole stands where an expression or a pattern does"),
301	    }
302	}
303	
304	/// A node of `arena` at `index`, in the seat it stands in, which must take a node of its arena.
305	fn held_filled(kind: HoleKind, arena: string, index: int) -> Filled {
306	    match kind {
307	        .Expression or .Tail -> if arena == "expr" { Filled.Expr(ExprId { index: index }) } else { misplaced(arena, "an expression") },
308	        .Binder -> if arena == "pat" { Filled.Pat(PatId { index: index }) } else { misplaced(arena, "a pattern") },
309	        rest -> Filled.Unplaceable("a held node stands where an expression or a pattern does"),
310	    }
311	}
312	
313	/// A node of the arena a run's item holds: its arena's word and its index.
314	type Held = { arena: string, index: int }
315	
316	/// The node a run's item holds, absent for an item that holds none.
317	fn held_at(item: Node) -> Held? {
318	    match item {
319	        .Many([.Name(arena), .Int(index)]) -> Held { arena: arena, index: index },
320	        rest -> null,
321	    }
322	}
323	
324	/// A run of held nodes in the seat it stands in: statements, or a run of expressions.
325	fn run_filled(kind: HoleKind, items: List<Node>) -> Filled {
326	    let held = [held_at(i) for i in items]
327	    if held.any(it == null) { return holds_no_node() }
328	    let run = [h! for h in held]
329	    match kind {
330	        .Statement or .Tail -> if run.all(it.arena == "stmt") { Filled.Stmts([StmtId { index: h.index } for h in run]) } else { misplaced_run("statements") },
331	        .Run -> if run.all(it.arena == "expr") { Filled.Exprs([ExprId { index: h.index } for h in run]) } else { misplaced_run("expressions") },
332	        rest -> Filled.Unplaceable("a run of held nodes stands where statements or a run do"),
333	    }
334	}
335	
336	fn holds_no_node() -> Filled { Filled.Unplaceable("a rewrite's hole holds no node") }
337	
338	fn misplaced(arena: string, seat: string) -> Filled {
339	    Filled.Unplaceable("a held `${arena}` node stands where ${seat} does")
340	}
341	
342	fn misplaced_run(seat: string) -> Filled {
343	    Filled.Unplaceable("a run holding another arena's nodes stands where ${seat} do")
344	}
