346	/// The template's scratch parse, made once.
347	fn scratch(lang: Language, source: string) -> Scratch? {
348	    let held: Scratch? = kept().get().get(source)
349	    if held != null { return held }
350	    let p = parse_program(lang, new_source_file("<means>", source), BlockWords {})
351	    if !p.voices.list.is_empty() { return null }
352	    let first? = p.stmts.first() else { return null }
353	    let q? = p.store.answer_of(first) else { return null }
354	    let made = Scratch { store: p.store, body: q }
355	    kept().put(source, made)
356	    made
357	}
