359	/// Declarations a generator's directives made, spliced into a store of their own: the statements,
360	/// and the words for each fill the splice couldn't place.
361	export type SplicedDecls = { store: SyntaxArena, stmts: List<StmtId>, refused: List<string>, unplaced: List<string> = [] }
362	
363	/// Each node of `sources` spliced as declarations into one store: every template copied from the
364	/// nodes `written` finds where it was written, else from its runs, and its nodes marked with the
365	/// file that wrote it, every hole filled at its seat with the value the generator gave it, each
366	/// lambda placed apart, and every block hygienic where it lands, in the file `here` names.
367	export fn generated_spliced(sources: List<Node>, here: string?, written: WrittenAt) -> SplicedDecls {
368	    let refused: Cell<List<string>> = Cell.new([])
369	    let sp = Splice {
370	        lang: avra(),
371	        store: new_node_store(),
372	        refused: refused,
373	        unplaced: list_cell(),
374	        spliced: map_cell(),
375	        binders: list_cell(),
376	        written: written,
377	        of: SpliceOf.Generator,
378	    }
379	    let stmts = flatten([sp.stmts(n) for n in sources])
380	    lambdas_apart(sp.store)
381	    binders_apart(sp.store, sp.spliced.get(), sp.binders.get(), here)
382	    SplicedDecls {
383	        store: sp.store,
384	        stmts: stmts,
385	        refused: sp.refused.get(),
386	        unplaced: sp.unplaced.get(),
387	    }
388	}
