390	/// What a splice copies: a generator's declarations, whose holes are values and whose nodes keep
391	/// their template's spans; or a sugar's meaning, whose holes are nodes of the store it rewrites and
392	/// whose nodes stand where the sugar does.
393	enum SpliceOf {
394	    Generator
395	    Meaning
396	}
397	
398	impl SpliceOf {
399	    /// Whether a hole's fill is a node of the store the splice lands in, by its arena and index.
400	    fn holds_nodes() -> bool { match self { .Meaning -> true, .Generator -> false } }
401	
402	    /// Whether the copied nodes keep the spans their template was written at.
403	    fn spanned_home() -> bool { match self { .Generator -> true, .Meaning -> false } }
404	}
405	
406	/// Templates being spliced into `store`, under `lang`, as `of` says: the words for what it couldn't
407	/// place gathered in `refused`, each read a hole spliced in by name, by its index, each binder a hole
408	/// named, and the scope names a meaning's copy marks `fresh`.
409	type Splice = {
410	    lang: Language,
411	    store: SyntaxArena,
412	    refused: Cell<List<string>>,
413	    /// The words for each fill no seat could hold, among `refused`: the template's own refusal,
414	    /// where the rest are this compiler's reading.
415	    unplaced: Cell<List<string>>,
416	    spliced: Cell<Map<string, bool>>,
417	    binders: Cell<List<PatId>>,
418	    /// Where each template copied was written, parsed.
419	    written: WrittenAt,
420	    of: SpliceOf,
421	    fresh: string? = null,
422	}
423	
424	impl Splice {
425	    /// A value in the seat its hole stands in: a node the store holds, where the splice's holes hold
426	    /// nodes; else a value. A run of templates has no expression position.
427	    fn filled(kind: HoleKind, node: Node) -> Filled {
428	        let held = if self.of.holds_nodes() { node_filled(kind, node) } else { null }
429	        if held != null { return held! }
430	        match kind {
431	            .Expression -> match node {
432	                .Many(_) -> Filled.Unplaceable(many_in_expression()),
433	                .Template(_, _, _, _) or .Name(_) or .Text(_) or .Int(_) or .Float(_) or .Bool(_) or .Interp(_, _) -> Filled.Expr(self.expr(node)),
434	            },
435	            .Name -> Filled.Name(names_of(node).first() ?? ""),
436	            .Binder -> self.binder(node),
437	            .Type -> Filled.Type(self.written_type(node)),
438	            .Statement or .Tail -> Filled.Stmts(self.stmts(node)),
439	            .Arm -> Filled.Arms(self.arms(node)),
440	            .Run -> Filled.Exprs(self.exprs(node)),
441	            .Fields -> Filled.Params(self.params(node)),
442	            .Inits -> Filled.Inits(self.inits(node)),
443	        }
444	    }
445	
446	    /// A template written in `file` at `at`, copied as `seat` takes it; a body of nothing but holes
447	    /// is its fills in that seat.
448	    fn copied(file: string, at: int, parts: List<string>, fills: List<Node>, seat: HoleKind) -> TemplateCopy {
449	        if bare_template(self.lang, parts) { return self.bare(fills, seat) }
450	        let sp = self
451	        let copy? = template_copied(
452	            self.lang,
453	            self.store,
454	            (self.written)(file, at),
455	            parts,
456	            [(kind: HoleKind) -> sp.filled(kind, fill) for fill in fills],
457	            seat,
458	            self.fresh,
459	            ForeignOrigin { path: file, spanned_home: self.of.spanned_home() },
460	        ) else {
461	            self.refused.push(unreadable_template(file, at))
462	            return TemplateCopy { stmts: [] }
463	        }
464	        if self.of.spanned_home() {
465	            let site = point_at(at)
466	            for e in copy.exprs { self.store.place_expr(e, site) }
467	            if !copy.placed { for s in copy.stmts { self.store.stmts.place(s.index, site) } }
468	        }
469	        // LICENSED loops.push_loop: a `Cell` takes one element per write, and no bulk write exists
470	        for w in copy.refused {
471	            self.refused.push(w)
472	            self.unplaced.push(w)
473	        }
474	        // LICENSED loops.push_loop: a `Cell` takes one element per write, and no bulk write exists
475	        for b in copy.binders { self.binders.push(b) }
476	        copy
477	    }
478	
479	    /// A body of nothing but holes, in the seat it is put in.
480	    fn bare(fills: List<Node>, seat: HoleKind) -> TemplateCopy {
481	        match seat {
482	            .Arm -> TemplateCopy { stmts: [], arms: flatten([self.arms(x) for x in fills]) },
483	            .Fields -> TemplateCopy { stmts: [], params: flatten([self.params(x) for x in fills]) },
484	            .Inits -> TemplateCopy { stmts: [], inits: joined_inits([self.inits(x) for x in fills]) },
485	            .Expression or .Statement or .Name or .Binder or .Type or .Run or .Tail -> TemplateCopy { stmts: flatten([self.stmts(x) for x in fills]) },
486	        }
487	    }
488	
489	    /// A value where statements stand: a template's, a run's each, any other its expression.
490	    fn stmts(node: Node) -> List<StmtId> {
491	        match node {
492	            .Template(file, at, parts, fills) -> self.copied(file, at, parts, fills, HoleKind.Statement).stmts,
493	            .Many(items) -> flatten([self.stmts(i) for i in items]),
494	            .Name(_) or .Text(_) or .Int(_) or .Float(_) or .Bool(_) or .Interp(_, _) -> [self.store.alloc_stmt(Stmt.ExprStmt(self.expr(node)))],
495	        }
496	    }
497	
498	    /// A value where one expression stands.
499	    fn expr(node: Node) -> ExprId {
500	        match node {
501	            .Template(file, at, parts, fills) -> self.template_expr(file, at, parts, fills),
502	            .Name(text) -> {
503	                let read = self.store.alloc_expr(Expr.Ident(Scoped(text)))
504	                self.spliced.put("${read.index}", true)
505	                read
506	            },
507	            .Text(text) -> self.store.alloc_expr(Expr.StrLit(text)),
508	            .Int(value) -> self.store.alloc_expr(Expr.IntLit(value)),
509	            .Float(bits) -> self.store.alloc_expr(Expr.FloatLit(bits)),
510	            .Bool(value) -> self.store.alloc_expr(Expr.BoolLit(value)),
511	            .Interp(parts, holes) -> {
512	                let holed = [self.expr(h) for h in holes]
513	                self.store.alloc_expr(Expr.Body("text", parts, holed, BodyView.None))
514	            },
515	            .Many(_) -> self.store.alloc_expr(Expr.Error),
516	        }
517	    }
518	
519	    /// A template as an expression: its one statement's value, or a block of its statements.
520	    fn template_expr(file: string, at: int, parts: List<string>, fills: List<Node>) -> ExprId {
521	        let stmts = self.copied(file, at, parts, fills, HoleKind.Expression).stmts
522	        let last? = stmts.last() else { return self.store.alloc_expr(Expr.Error) }
523	        let value? = self.store.answer_of(last) else { return self.store.alloc_expr(Expr.Block(stmts)) }
524	        if stmts.length == 1 { value } else { self.store.alloc_expr(Expr.Block(stmts)) }
525	    }
526	
527	    /// A value where a run of expressions stands: a run's each, or the one it is.
528	    fn exprs(node: Node) -> List<ExprId> {
529	        match node {
530	            .Many(items) -> [self.expr(i) for i in items],
531	            .Template(_, _, _, _) or .Name(_) or .Text(_) or .Int(_) or .Float(_) or .Bool(_) or .Interp(_, _) -> [self.expr(node)],
532	        }
533	    }
534	
535	    /// A value where match arms stand.
536	    fn arms(node: Node) -> List<Arm> {
537	        match node {
538	            .Template(file, at, parts, fills) -> self.copied(file, at, parts, fills, HoleKind.Arm).arms,
539	            .Many(items) -> flatten([self.arms(i) for i in items]),
540	            .Name(_) or .Text(_) or .Int(_) or .Float(_) or .Bool(_) or .Interp(_, _) -> [],
541	        }
542	    }
543	
544	    /// A value where a run of fields stands: each template's fields.
545	    fn params(node: Node) -> List<Param> {
546	        match node {
547	            .Template(file, at, parts, fills) -> self.copied(file, at, parts, fills, HoleKind.Fields).params,
548	            .Many(items) -> flatten([self.params(i) for i in items]),
549	            .Name(_) or .Text(_) or .Int(_) or .Float(_) or .Bool(_) or .Interp(_, _) -> [],
550	        }
551	    }
552	
553	    /// A value where a record literal's fields stand: each literal's fields.
554	    fn inits(node: Node) -> Inits {
555	        match node {
556	            .Template(file, at, parts, fills) -> self.copied(file, at, parts, fills, HoleKind.Inits).inits,
557	            .Many(items) -> joined_inits([self.inits(i) for i in items]),
558	            .Name(_) or .Text(_) or .Int(_) or .Float(_) or .Bool(_) or .Interp(_, _) -> no_inits(),
559	        }
560	    }
561	
562	    /// A value where a binder stands: a number or a truth is a literal pattern, anything else the
563	    /// names it spells.
564	    fn binder(node: Node) -> Filled {
565	        match node {
566	            .Int(value) -> Filled.Pat(self.store.alloc_pat(Pat.Lit(self.store.alloc_expr(Expr.IntLit(value))))),
567	            .Bool(value) -> Filled.Pat(self.store.alloc_pat(Pat.Lit(self.store.alloc_expr(Expr.BoolLit(value))))),
568	            .Template(_, _, _, _) or .Many(_) or .Name(_) or .Text(_) or .Float(_) or .Interp(_, _) -> Filled.Names(names_of(node)),
569	        }
570	    }
571	
572	    /// A value where a written type stands: a name as the type it names, any other spelling read with
573	    /// the language's `type` rule.
574	    fn written_type(node: Node) -> TypeRef {
575	        let text = names_of(node).first() ?? ""
576	        if all_codes(text, is_name_cont) { return named_ref(text) }
577	        parse_type_ref(self.lang, text) ?? named_ref(text)
578	    }
579	}
