581	/// The names a value spells: one, or several for a run.
582	fn names_of(node: Node) -> List<string> {
583	    match node {
584	        .Name(text) or .Text(text) -> [text],
585	        .Int(value) -> ["${value}"],
586	        .Many(items) -> flatten([names_of(i) for i in items]),
587	        .Template(_, _, _, _) or .Float(_) or .Bool(_) or .Interp(_, _) -> [],
588	    }
589	}
