591	/// The empty place at `at`.
592	fn point_at(at: int) -> Span { Span { lo: at, hi: at } }
593	
594	/// Each lambda of a copy placed where no other stands: a copy's places are its template's, and one
595	/// template copied twice would put two lambdas at one place, which a lift names them by.
596	fn lambdas_apart(store: SyntaxArena) {
597	    for at in 0..store.exprs.count() {
598	        let e = ExprId { index: at }
599	        if store.lambda_parts(e) != null { store.place_expr(e, point_at(at)) }
600	    }
601	}
602	
603	/// A binder never captures a name written on the other side of a hole. Inside each fn, a lambda
604	/// parameter or a `let` a template wrote that shares its name with one of the fn's own seats, where a
605	/// read of that name a hole spliced in (`spliced`, by index) stands in its reach, means the seat: the
606	/// binder and each read of it the template wrote are renamed apart. And an arm's binder a hole named
607	/// (`holed`) that shares a seat's name, where a read of that name the template wrote stands in the
608	/// arm, leaves that read to the seat: the binder and each spliced read of it are renamed apart. Every
609	/// block keeps the hygiene law (`lets_kept_apart`), the code landing in the file `here` names.
610	fn binders_apart(store: SyntaxArena, spliced: Map<string, bool>, holed: List<PatId>, here: string?) {
611	    for s in store.stmt_ids() {
612	        let f? = store.fn_parts(s) else { continue }
613	        let seats = [p.name.of for p in f.params]
614	        for e in store.every_expr(f.body) {
615	            let stmts = store.block_stmts(e)
616	            if stmts != null { store.lets_kept_apart(stmts!, here) }
617	            if seats.is_empty() { continue }
618	            let lam = store.lambda_parts(e)
619	            if lam != null { lambda_apart(store, spliced, seats, e, lam!) }
620	            if stmts != null { lets_apart(store, spliced, seats, stmts!) }
621	            let arms = store.match_arms(e)
622	            if arms != null { for a in arms! { arm_apart(store, spliced, holed, seats, a) } }
623	        }
624	    }
625	}
626	
627	/// The lambda `e`'s parameters a template wrote that a seat of its fn's shares a name with, where a
628	/// spliced read of the name stands in its body, renamed apart with each read of them it wrote.
629	fn lambda_apart(
630	    store: SyntaxArena,
631	    spliced: Map<string, bool>,
632	    seats: List<string>,
633	    e: ExprId,
634	    lam: LambdaParts,
635	) {
636	    let home? = store.home_of(e) else { return }
637	    let inside = store.every_expr(lam.body)
638	    let clashing = [p.name.of for p in lam.params if seats.contains(p.name.of) && spliced_read(store, spliced, inside, p.name.of)]
639	    if clashing.is_empty() { return }
640	    renamed_reads(store, spliced, inside, clashing, home)
641	    store
642	        .exprs
643	        .replaced(
644	            e.index,
645	            Expr
646	                .Lambda(
647	                    [if clashing.contains(p.name.of) { p with { name: Scoped(apart_name(p.name.of)) } } else { p } for p in lam.params],
648	                    lam.body,
649	                ),
650	        )
651	}
652	
653	/// Each `let` a template wrote among `stmts` that a seat of its fn's shares a name with, where a
654	/// spliced read of the name stands after it, renamed apart with each later read of it the template
655	/// wrote. A `let` whose name a hole brought binds the landing's name: it shadows the seat from its
656	/// line on, as any `let` does.
657	fn lets_apart(
658	    store: SyntaxArena,
659	    spliced: Map<string, bool>,
660	    seats: List<string>,
661	    stmts: List<StmtId>,
662	) {
663	    for j, s in stmts {
664	        let n? = store.let_name(s) else { continue }
665	        if !seats.contains(n) { continue }
666	        let home? = store.seat_home(s, LandedSeat.Names) else { continue }
667	        let renamed? = let_renamed(store.stmt(s), apart_name(n)) else { continue }
668	        let reads = flatten([store.every_expr(x) for x in store.stmts_exprs(stmts.drop(j + 1))])
669	        if !spliced_read(store, spliced, reads, n) { continue }
670	        renamed_reads(store, spliced, reads, [n], home)
671	        store.stmt_replaced(s, renamed)
672	    }
673	}
674	
675	/// The binders of the arm `a` a hole named that a seat of its fn's shares a name with, where a read
676	/// of the name the template wrote stands in the arm, renamed apart with each spliced read of them.
677	fn arm_apart(
678	    store: SyntaxArena,
679	    spliced: Map<string, bool>,
680	    holed: List<PatId>,
681	    seats: List<string>,
682	    a: Arm,
683	) {
684	    let reads = flatten([store.every_expr(x) for x in some_list(a.guard).concat([a.value])])
685	    let named = [b for p in a.pats for b in store.pattern_binds(p) if holed.contains(b.pat) && seats.contains(b.name)]
686	    for b in named {
687	        if !written_read(store, spliced, reads, b.name) || store.bind_name(b.pat) == null { continue }
688	        for x in reads { if store.ident_name(x) == b.name && spliced.has("${x.index}") { store.exprs.replaced(x.index, Expr.Ident(Scoped(apart_name(b.name)))) } }
689	        store.pat_replaced(b.pat, Pat.Bind(Scoped(apart_name(b.name))))
690	    }
691	}
692	
693	/// Whether a read of `name` among `reads` is one the template wrote.
694	fn written_read(store: SyntaxArena, spliced: Map<string, bool>, reads: List<ExprId>, name: string) -> bool {
695	    reads.any((x) -> store.ident_name(x) == name && !spliced.has("${x.index}"))
696	}
697	
698	/// Whether a read of `name` among `reads` is one a hole spliced in.
699	fn spliced_read(store: SyntaxArena, spliced: Map<string, bool>, reads: List<ExprId>, name: string) -> bool {
700	    reads.any((x) -> store.ident_name(x) == name && spliced.has("${x.index}"))
701	}
702	
703	/// Each read among `reads` of one of `names` the template at `home` wrote, renamed apart.
704	fn renamed_reads(
705	    store: SyntaxArena,
706	    spliced: Map<string, bool>,
707	    reads: List<ExprId>,
708	    names: List<string>,
709	    home: string,
710	) {
711	    for x in reads {
712	        let n? = store.ident_name(x) else { continue }
713	        if names.contains(n) && !spliced.has("${x.index}") && store.home_of(x) == home { store.exprs.replaced(x.index, Expr.Ident(Scoped(apart_name(n)))) }
714	    }
715	}
