1	//! A template's HOLES: a hole is a NAME no program can write — `${k}`,
2	//! `k` its index in the quote — so every builder mints its ordinary
3	//! node with a placeholder name, and the seat that name sits in is
4	//! the hole's kind.
5	
6	use @std.meta.{derive}
7	use @std.program.saved_derive.{Saved}
8	use @std.text.{parse_int}
9	
10	/// A hole-bearing name's runs and the holes between them: `l${2}_x`
11	/// is `parts: ["l", "_x"], holes: [2]`. A LONE hole has two empty
12	/// parts.
13	export type HoleName = { parts: List<string>, holes: List<int> }
14	
15	impl HoleName {
16	    /// Whether the name is the hole and nothing else.
17	    fn lone() -> bool { self.holes.length == 1 && self.parts.all(it.is_empty()) }
18	}
19	
20	/// The name a hole-bearing token wears — the inverse of `hole_name`.
21	export fn placeholder(parts: List<string>, holes: List<int>) -> string {
22	    let woven = [parts[j] + "\${${k}}" for j, k in holes]
23	    woven.join("") + parts[holes.length]
24	}
25	
26	/// The holes a name carries, or null for a written name. `$` spells
27	/// no written name, so the test is one character.
28	export fn hole_name(text: string) -> HoleName? {
29	    if !text.contains("\$") { return null }
30	    mut parts: List<string> = []
31	    mut holes: List<int> = []
32	    mut run = 0
33	    mut i = 0
34	    while i < text.length {
35	        if text.char_code(i) == 36 && i + 1 < text.length && text.char_code(i + 1) == 123 {
36	            let close = closing(text, i + 2)
37	            parts.push(text.substring(run, i))
38	            holes.push(digits(text.substring(i + 2, close)))
39	            i = close + 1
40	            run = i
41	        } else {
42	            i = i + 1
43	        }
44	    }
45	    parts.push(text.substring(run, text.length))
46	    HoleName { parts: parts, holes: holes }
47	}
48	
49	/// The `}` at or after `from` — a hole's index has no other closer.
50	fn closing(text: string, from: int) -> int {
51	    mut j = from
52	    while j < text.length && text.char_code(j) != 125 { j = j + 1 }
53	    j
54	}
55	
56	/// A hole's index — always digits the compiler minted, never text a
57	/// program wrote, so absence here is a defect and not a case to
58	/// answer for.
59	fn digits(s: string) -> int {
60	    parse_int(s)!
61	}
62	
63	/// What a hole's seat takes — typed by POSITION at the quote.
64	@derive(Saved)
65	export enum HoleKind {
66	    /// a lone name where an expression stands
67	    Expression
68	    /// a name, or part of one: a declaration's, a field's, a
69	    /// variant's, a property's
70	    Name
71	    /// a lone binder in a pattern
72	    Binder
73	    /// a written type's name
74	    Type
75	    /// a lone name standing as a whole statement
76	    Statement
77	    /// a lone name standing as a whole match arm
78	    Arm
79	    /// a lone `${..name}` among a list of expressions — a call's
80	    /// arguments, a list literal's elements
81	    Run
82	    /// a lone name standing as a whole entry of a type's fields or a
83	    /// fn's parameters
84	    Fields
85	    /// a lone name standing as a whole field of a record literal
86	    Inits
87	    /// a lone name standing as a block's LAST statement — the block's
88	    /// value when it is an expression, else statements joining the block
89	    Tail
90	}
91	
92	impl HoleKind {
93	    /// The position a hole of this kind stands in, as a voice names it.
94	    fn position_word() -> string {
95	        match self {
96	            .Expression -> "expression",
97	            .Name -> "name",
98	            .Binder -> "binder",
99	            .Type -> "type",
100	            .Statement -> "statement",
101	            .Arm -> "arm",
102	            .Run -> "run",
103	            .Fields -> "field",
104	            .Inits -> "record-field",
105	            .Tail -> "block-tail",
106	        }
107	    }
108	
109	    /// What a hole of this kind takes, as a voice names it.
110	    fn takes_word() -> string {
111	        match self {
112	            .Expression -> "`Code`, an `int` or a `bool`",
113	            .Name -> "a `string`, an `int` or a named meta value",
114	            .Binder -> "a name, or a `List<string>` of them",
