151	/// What a hole's VALUE is, as the seat law sees it: a template of a
152	/// kind, a list of them, an int, a bool, text, a list of texts, a
153	/// named meta value.
154	export enum FillClass {
155	    Template(kind: MetaKind)
156	    Templates(kind: MetaKind)
157	    Int
158	    Bool
159	    /// An arena id — `ExprId` — read where a rewrite's hole stands.
160	    Id
161	    /// A pattern's arena id — `PatId` — read where a rewrite's pattern stands.
162	    PatId
163	    Text
164	    Texts
165	    Named
166	    /// A `features.Code` HANDLE — the compiler's own, never
167	    /// `@std.meta.Code` — spliced as its own source text: an
168	    /// expression seat only, and a rule's ONE way to answer a
169	    /// rewrite around a bound hole (`quote { ${x} ?? ${d} }` with
170	    /// `x` bound from a pattern).
171	    Held
172	    /// A `Format` head — `@std.meta`'s pattern — naming the record its
173	    /// instance mints: where a type or an expression stands.
174	    Pattern
175	    /// A meaning's subject handle (`features.TypedCode`), spliced as the node
176	    /// it holds: where an expression stands.
177	    Node
178	    /// A run of a meaning's handles, spliced as the nodes they hold: where
179	    /// statements, a run, or a block's tail stand.
180	    Nodes
181	}
