183	/// THE SEAT LAW, one registry read by typing and by the splice: what
184	/// each seat takes. A text in an expression seat is refused for
185	/// AMBIGUITY (`literal` or `name`), which is its own voice.
186	export fn fits(class: FillClass, kind: HoleKind) -> bool {
187	    match kind {
188	        .Expression -> match class {
189	            .Template(k) -> k is .Code,
190	            .Int or .Bool or .Id or .Held or .Pattern or .Node -> true,
191	            .Templates(_) or .Text or .Texts or .Named or .PatId or .Nodes -> false,
192	        },
193	        .Name -> match class {
194	            .Text or .Int or .Named -> true,
195	            .Template(_) or .Templates(_) or .Bool or .Texts or .Id or .PatId or .Held or .Pattern or .Node or .Nodes -> false,
196	        },
197	        .Binder -> match class {
198	            .Text or .Int or .Bool or .Named or .Texts or .PatId -> true,
199	            .Template(_) or .Templates(_) or .Id or .Held or .Pattern or .Node or .Nodes -> false,
200	        },
201	        .Type -> match class {
202	            .Text or .Named or .Pattern -> true,
203	            .Template(_) or .Templates(_) or .Int or .Bool or .Texts or .Id or .PatId or .Held or .Node or .Nodes -> false,
204	        },
205	        .Statement -> match class {
206	            .Template(k) or .Templates(k) -> !(k is .Arms),
207	            .Nodes -> true,
208	            .Int or .Bool or .Text or .Texts or .Named or .Id or .PatId or .Held or .Pattern or .Node -> false,
209	        },
210	        .Arm -> match class {
211	            .Template(k) or .Templates(k) -> k is .Arms,
212	            .Int or .Bool or .Text or .Texts or .Named or .Id or .PatId or .Held or .Pattern or .Node or .Nodes -> false,
213	        },
214	        .Run -> match class {
215	            .Templates(k) -> k is .Code,
216	            .Nodes -> true,
217	            .Template(_) or .Int or .Bool or .Text or .Texts or .Named or .Id or .PatId or .Held or .Pattern or .Node -> false,
218	        },
219	        .Fields -> match class {
220	            .Template(k) or .Templates(k) -> declares(k),
221	            .Int or .Bool or .Text or .Texts or .Named or .Id or .PatId or .Held or .Pattern or .Node or .Nodes -> false,
222	        },
223	        .Inits -> match class {
224	            .Template(k) or .Templates(k) -> expresses(k),
225	            .Int or .Bool or .Text or .Texts or .Named or .Id or .PatId or .Held or .Pattern or .Node or .Nodes -> false,
226	        },
227	        .Tail -> match class {
228	            .Template(k) or .Templates(k) -> !(k is .Arms),
229	            .Int or .Bool or .Id or .Held or .Pattern or .Node or .Nodes -> true,
230	            .Text or .Texts or .Named or .PatId -> false,
231	        },
232	    }
