245	/// The kind a body of NOTHING BUT HOLES wears: its first hole's —
246	/// several expressions being statements — and every other hole must
247	/// agree, or the quote refuses a mix.
248	export fn holes_kind(classes: List<FillClass>) -> MetaKind? {
249	    let first? = classes.first() else { return MetaKind.Stmts }
250	    let own? = class_kind(first) else { return null }
251	    let kind = if classes.length == 1 { own } else { many_of(own) }
252	    if classes.all(agrees(it, kind)) { kind } else { null }
