255	/// The kind a fill alone would make a quote of holes.
256	export fn class_kind(c: FillClass) -> MetaKind? {
257	    match c {
258	        .Template(k) -> k,
259	        .Templates(k) -> many_of(k),
260	        .Int or .Bool or .Held or .Pattern -> MetaKind.Code,
261	        .Id or .PatId or .Node or .Nodes -> MetaKind.Rewrite,
262	        .Text or .Texts or .Named -> null,
