295	/// The template kind `ty` is among `@std/meta`'s, each named by `meta`; absent for a type that's none.
296	export fn signed_template_kind(ty: SignedType, meta: fn(string) -> SignedType?) -> MetaKind? {
297	    if ty.nullable() || ty.dynamic { return null }
298	    [MetaKind.Code, MetaKind.Stmts, MetaKind.Arms, MetaKind.Decls, MetaKind.Rewrite]
299	        .find((k) -> meta(meta_name(k))?.names_as(ty) ?? false)
300	}
