302	/// What a hole's value of type `ty` is, as a row lifts it: a template, a list of templates, a handle
303	/// on the tree being rewritten or a list of them, code a rule bound, an arena id, a number, a truth,
304	/// text, a list of texts, or a meta value naming one declaration; each type the toolchain declares
305	/// named by `toolchain` (a module, then a name). Absent for any other.
306	export fn signed_fill_class(ty: SignedType, toolchain: fn(string, string) -> SignedType?) -> FillClass? {
307	    let meta = (n: string) -> toolchain(META_MODULE, n)
308	    let own = signed_template_kind(ty, meta)
309	    if own != null { return FillClass.Template(own!) }
310	    let compiler = compiler_fill(ty, toolchain)
311	    if compiler != null { return compiler }
312	    let elem = ty.listed()
313	    if elem != null { return listed_fill_class(elem!, toolchain, meta) }
314	    if NAMED_META.any((n) -> meta(n)?.names_as(ty) ?? false) { return FillClass.Named }
315	    let own? = ty.own() else { return null }
316	    match own {
317	        .Str -> FillClass.Text,
318	        .Int -> FillClass.Int,
319	        .Bool -> FillClass.Bool,
320	        .Float or .Ptr or .Void or .Bytes or .List or .Map or .Cell or .Range or .Result or .Task or .Tasks -> null,
321	    }
322	}
323	
324	/// What a hole holding a list of `elem` is: nodes, templates or texts; absent for any other list.
325	fn listed_fill_class(
326	    elem: SignedType,
327	    toolchain: fn(string, string) -> SignedType?,
328	    meta: fn(string) -> SignedType?,
329	) -> FillClass? {
330	    if names_own(elem, toolchain, OWN_FEATURES, "TypedCode") { return FillClass.Nodes }
331	    let inner = signed_template_kind(elem, meta)
332	    if inner != null { return FillClass.Templates(inner!) }
333	    if elem.owns(OwnType.Str) { FillClass.Texts } else { null }
334	}
