336	/// What a hole holding one of the compiler's own values fills: a meaning's handle the node, a rule's
337	/// code its text, an arena id the number; absent for any other type.
338	fn compiler_fill(ty: SignedType, toolchain: fn(string, string) -> SignedType?) -> FillClass? {
339	    if names_own(ty, toolchain, OWN_FEATURES, "TypedCode") { return FillClass.Node }
340	    if held_splicer(ty, toolchain) != null || rule_subject(ty) { return FillClass.Held }
341	    if names_own(ty, toolchain, OWN_CORE, "ExprId") { return FillClass.Id }
342	    if names_own(ty, toolchain, OWN_CORE, "PatId") { FillClass.PatId } else { null }
343	}
344	
345	/// Whether `ty` is the type `module` declares as `name`.
346	fn names_own(
347	    ty: SignedType,
348	    toolchain: fn(string, string) -> SignedType?,
349	    module: string,
350	    name: string,
351	) -> bool {
352	    toolchain(module, name)?.names_as(ty) ?? false
353	}
354	
355	/// The modules declaring the compiler's own values a hole may hold, and `@std/meta`.
356	const OWN_FEATURES: string = "@std.avrac.features"
357	
358	const OWN_CORE: string = "@std.avrac.core"
359	
360	/// The module `@std/meta` is to the toolchain.
361	export const META_MODULE: string = "@std.meta"
362	
363	/// The `@std/meta` values that name one declaration, spliced by its name.
364	const NAMED_META: List<string> = ["Fn", "Type", "Named", "Trait", "Field", "Variant", "Param"]
365	
366	/// A handle a quote pattern binds its holes as, by its type's name among `@std/avrac`'s features: the
367	/// verb that lists one at each place of a run, and the verb that splices a held one into a template
368	/// as its text, absent for one spliced as the node it holds.
369	export type CodeHandle = { handle: string, runs: string, splices: string? }
370	
371	/// Every handle a quote pattern binds: a rule's analysed code, a syntax rule's syntax, a meaning's
372	/// typed code.
373	export once fn code_handles() -> List<CodeHandle> {
374	    table<CodeHandle> {
375	        handle      | runs           | splices
376	        "Code"      | "run_coded"    | "spliced_text"
377	        "Syntax"    | "syntax_coded" | "spliced_syntax"
378	        "TypedCode" | "typed_coded"  | null
379	    }
380	}
381	
382	/// The verb that splices a held handle of `ty` into a template as its text; absent for a type no
383	/// handle spliced as text is.
384	export fn held_splicer(ty: SignedType, toolchain: fn(string, string) -> SignedType?) -> string? {
385	    let h? = code_handles()
386	        .find((c) -> c.splices != null && names_own(ty, toolchain, OWN_FEATURES, c.handle)) else { return null }
387	    h.splices
388	}
