    let placed = (p: FindingAt?) -> if p == null { null } else { file_placed(engine, file, home, p!) }
    f with { at: placed(f.at), named: placed(f.named), fixes: [fix_in_file(engine, file, home, x) for x in f.fixes], aside: aside_in_file(engine, file, at, f.aside), item: null }
}

/// A finding in an item a generator made, whose nodes `store` holds: homed in the file whose template
/// wrote the node it stands at, its places that file's as the template's copied spans keep them. A
/// finding at a node no template wrote — a value the generator made — stands nowhere in a file, and
/// is said of the file whose generator made it. Its edits would write the template, never the
/// program, and aren't offered.
fn made_finding(store: SyntaxArena, f: LawFinding) -> LawFinding {
    let place? = f.at else { return f with { named: null, fixes: [], aside: null, item: null } }
    let home? = template_home_at(store, place) else { return f with { at: null, named: null, fixes: [], aside: null, item: null } }
    f with { home: home, named: if template_home_at(store, f.named ?? place) == home { f.named } else { null }, fixes: [], aside: null, item: null }
}

/// The file whose template wrote the node of `store` standing at `place`, by package and path: the
/// node spanned exactly there, else the narrowest one holding it, of those a template wrote.
fn template_home_at(store: SyntaxArena, place: FindingAt) -> string? {
    let spanned = [Homed { path: o!.path, span: sp! } for i in 0..store.expr_count() for o in [store.foreign_of(ExprId { index: i })] if o != null && o!.spanned_home for sp in [store.expr_span(ExprId { index: i })] if sp != null]
        .concat(
            [Homed { path: o!.path, span: sp! } for i in 0..store.stmts.count() for o in [store.stmt_origins.at(i)] if o != null && o!.spanned_home for sp in [store.stmt_span(StmtId { index: i })] if sp != null],
        )
    let holding = [h for h in spanned if h.span.lo <= place.lo && place.hi <= h.span.hi]
    let narrowest? = sorted_by(holding, (a, b) -> a.span.hi - a.span.lo < b.span.hi - b.span.lo)
        .first() else { return null }
    narrowest.path
}

