/// fn is, and a twin beside it; a method's wrap with its moved body a method of its owner and its
/// wrapper apart.
fn items_spliced(
    engine: QueryEngine,
    file: SourceFileAddress,
    name: string,
    made: List<Directive>,
    method: MethodSite? = null,
) -> GeneratedItems {
    let unread = flatten([unread_homes(engine, d.source!.node) for d in made if d.source != null])
    if !unread.is_empty() { return homes_unread(unread) }
    let spliced = generated_spliced(
        [d.source!.node for d in made if d.source != null],
        template_home(file),
        (home: string, at: int) -> written_quote(engine, home, at),
    )
    let wraps = made.any(it.wraps)
    if wraps && method != null { return method_wrap(engine, method!, name, spliced) }
    let moved: StmtId? = if wraps { moved_body(engine, file, name, spliced.store) } else { null }
    let unwrapped = if wraps { wrap_said(spliced.store, spliced.stmts, name, moved) } else { [] }
    let twins = [twin_of(engine, file, name, d.twin, spliced.store) for d in made if d.source == null && !d.twin.is_empty()]
    let stmts = spliced
        .stmts
        .concat(some_list(moved))
        .concat(flatten([some_list(t) for t in twins]))
    GeneratedItems {
        items: if stmts.is_empty() || !unwrapped.is_empty() { [] } else { [GeneratedItem { tape: tape_of_item(spliced.store, stmts), wraps: wraps }] },
        said: spliced
            .refused
            .concat(if twins.any(it == null) { [twin_unmade(name)] } else { [] })
            .concat(unwrapped)
            .concat(
                if stmts.is_empty() && made.all(it.twin.is_empty()) { some_list(unplaced(made)) } else { [] },
            ),
        problems: [KeptProblem {
            message: w,
            help: null,
            kind: null,
            warning: false,
            at: null,
            home: null,
            unplaced: true,
        } for w in spliced.unplaced],
    }
}

/// Each file a template among `n` and the nodes it holds names that this program does not read.
fn unread_homes(engine: QueryEngine, n: Node) -> List<string> {
    match n {
        .Template(home, _, _, fills) -> if home_read(engine, home) { [] } else { [home] }
            .concat(flatten([unread_homes(engine, f) for f in fills])),
        .Interp(_, holes) -> flatten([unread_homes(engine, h) for h in holes]),
        .Many(items) -> flatten([unread_homes(engine, i) for i in items]),
        .Name(_) or .Text(_) or .Int(_) or .Float(_) or .Bool(_) -> [],
    }
}

/// Whether the file `home` names is one this program reads: a source of the package it names.
fn home_read(engine: QueryEngine, home: string) -> bool {
    let at? = template_file(home) else { return false }
    package_sources(engine, at.package_name, "src").contains(at.path_in_package)
}

/// Directives whose templates name files this program does not read, `homes`: nothing spliced, each
/// file said once.
fn homes_unread(homes: List<string>) -> GeneratedItems {
    GeneratedItems {
        items: [],
        said: [],
        problems: [KeptProblem {
            message: h,
            help: null,
            kind: null,
            warning: false,
            at: null,
            home: null,
            unread_home: true,
        } for j, h in homes if homes.index_of(h) == j],
    }
}

