/// A binder never captures a name written on the other side of a hole. Inside each fn, a lambda
/// parameter or a `let` a template wrote that shares its name with one of the fn's own seats, where a
/// read of that name a hole spliced in (`spliced`, by index) stands in its reach, means the seat: the
/// binder and each read of it the template wrote are renamed apart. And an arm's binder a hole named
/// (`holed`) that shares a seat's name, where a read of that name the template wrote stands in the
/// arm, leaves that read to the seat: the binder and each spliced read of it are renamed apart. Every
/// block keeps the hygiene law (`lets_kept_apart`), the code landing in the file `here` names.
fn binders_apart(store: SyntaxArena, spliced: Map<string, bool>, holed: List<PatId>, here: string?) {
    for s in store.stmt_ids() {
        let f? = store.fn_parts(s) else { continue }
        let seats = [p.name.of for p in f.params]
        for e in store.every_expr(f.body) {
            let stmts = store.block_stmts(e)
            if stmts != null { store.lets_kept_apart(stmts!, here) }
            if seats.is_empty() { continue }
