/// module exports it, and its face — what a reader of the name depends on, so a change that leaves
/// it standing leaves every reader standing.
@derive(Saved)
export type TapeName = { name: string, kind: int, exported: bool, face: ContentHash }

/// An item's tape. `meaning_hash` and `above_hash` stand for their sections, computed once;
/// `declares` says what the item names and `about` what its language keeps of it besides, both
/// read without its nodes.
@derive(Saved)
export type SyntaxTape = {
    meaning_hash: ContentHash,
    meaning: TapeMeaning,
    above_hash: ContentHash,
    above: TapeSection,
    places: TapePlaces,
    declares: List<TapeName>,
    about: Bytes?,
}

/// The tape saved at `tape`, read back whole.
export fn tape_read(tape: SavedAt<SavedRecord>) -> SyntaxTape { SyntaxTape.read_from(tape.source, tape.node) }

/// What the tape saved at `tape` says about its item, read where it lies.
export fn tape_about(tape: SavedAt<SavedRecord>) -> Bytes? { SyntaxTape.about_in(tape.source, tape.node) }

/// The names the tape saved at `tape` declares, read where they lie.
