/// The whole diagnostic as terminal text — the kind is the bracket.
export fn render(d: Diag, src: SourceFile) -> string {
    render_with(d, (l: Loc) -> src)
}

/// The file a frame's position is an offset into: none when the frame has
/// no place or its place names no file.
fn frame_files(f: Frame) -> List<string> {
    let at? = f.loc else { return [] }
    let name? = at.file else { return [] }
    [name]
}

/// Every file a diagnostic's frames locate into, in frame order: the
/// files whose text a rendering reads offsets of.
export fn located_files(d: Diag) -> List<string> {
    flatten([frame_files(f) for f in [d.primary].concat(d.secondary)])
}

/// The diagnostic rendered over MANY sources — each frame's window
/// comes from the file its Loc names (a Loc naming none reads the
/// first); a file no source answers to renders its label alone.
export fn render_among(d: Diag, sources: List<SourceFile>) -> string {
    render_with(d, (l: Loc) -> source_named(sources, l.file))
}

/// Diagnostics rendered over many sources, one after another, a blank line between each: how every
/// report says what it found.
export fn rendered_among(ds: List<Diag>, sources: List<SourceFile>) -> string {
    joined([render_among(d, sources) for d in ds], "\n\n")
}

impl Diag {
    /// This diagnostic wrapping `e`: its chain flattened once, here, into the lines it prints.
    fn caused_by(e: dyn Error) -> Diag { self with { cause_lines: causes_of(e) } }
}

fn source_named(sources: List<SourceFile>, file: string?) -> SourceFile? {
    if file == null { sources[0] } else { sources.find(it.file == file) }
}

/// One frame: a window from the source its Loc picks; with no Loc, or a
/// Loc into a file no source answers to, its label alone — a window
/// over the wrong text would read offsets that are not there.
fn framed(f: Frame, pick: fn(Loc) -> SourceFile?) -> List<string> {
    let at? = f.loc else { return unplaced(f.label) }
    let src? = pick(at) else { return unplaced("${at.file ?? "<source>"}: ${f.label ?? ""}") }
