/// it (`item_start`): an item an edit above only moved reads as it did, and so does every answer
/// worked out of it, each place it holds counted from the item's own start.
@derive(Saved)
export type ItemUnder = { text: string, context: Bytes, print: int? = null }

/// A file's items, each with the context it reads under.
export fn items_under(engine: QueryEngine, file: SourceFileAddress) -> List<ItemUnder> {
    [item_under(engine, file, at) for at in item_ids(engine, file)]
}

/// How many items a file has.
@cut_query
export fn item_count(engine: QueryEngine, file: SourceFileAddress) -> int { file_items(engine, file).length }

/// THE ITEMS OF A FILE BY IDENTITY: each written item's id, in the order the file holds them. An
/// item's id is its own (`item_id_of`), never its place, so an item added or taken away renumbers
/// nothing else, and every question asked of an item by its id stands across it.
@cut_query
export fn item_ids(engine: QueryEngine, file: SourceFileAddress) -> List<int> { [i.id for i in file_items(engine, file)] }

/// Whether `file` has the written item `at`: what an item added or taken away beside it leaves
/// standing.
@cut_query
export fn item_held(engine: QueryEngine, file: SourceFileAddress, at: int) -> bool { item_parts_part(engine, file, held_part(at)) != null }

/// Whether `file` holds a written item at all: what an item added or taken away beside another
    let texts = [ItemText { start: span.start, text: t, print: fp_str(t) } for span in item_spans(avra_columns(text), text.length) for t in [text.substring(span.start, span.end)]]
    let keys = [item_key(i.text) for i in texts]
    let ids = item_ids_of(keys)
    [i with { id: ids[k] } for k, i in texts]
}

/// The ids of items keyed `keys`, in order: each its key's and the count of earlier items of that key
/// (`item_id_of`), and where two of those meet, the later moved on past every id taken.
fn item_ids_of(keys: List<string>) -> List<int> {
    mut met: Map<string, int> = {}
    mut taken: Map<string, bool> = {}
    mut ids: List<int> = []
    for key in keys {
        let nth = met.get(key) ?? 0
        met.set(key, nth + 1)
        mut id = item_id_of(key, nth)
        while taken.has("${id}") { id = (id + 1) % GENERATED_FIRST }
        taken.set("${id}", true)
        ids.push(id)
    }
    ids
}

/// The id of the `nth` item of a file keyed `key`: a number under `GENERATED_FIRST` that only the
/// item's own key and the items of that key before it decide.
fn item_id_of(key: string, nth: int) -> int { fp_str("${key}#${nth}") % GENERATED_FIRST }
