export fn generated_spliced(sources: List<Node>, here: string?, written: WrittenAt) -> SplicedDecls {
    let refused: Cell<List<string>> = Cell.new([])
    let sp = Splice {
        lang: avra(),
        store: new_node_store(),
        refused: refused,
        unplaced: list_cell(),
        spliced: map_cell(),
        binders: list_cell(),
        written: written,
        of: SpliceOf.Generator,
    }
    let stmts = flatten([sp.stmts(n) for n in sources])
    lambdas_apart(sp.store)
    binders_apart(sp.store, sp.spliced.get(), sp.binders.get(), here)
    SplicedDecls {
        store: sp.store,
        stmts: stmts,
        refused: sp.refused.get(),
        unplaced: sp.unplaced.get(),
    }
}

/// What a splice copies: a generator's declarations, whose holes are values and whose nodes keep
/// their template's spans; or a sugar's meaning, whose holes are nodes of the store it rewrites and
/// whose nodes stand where the sugar does.
enum SpliceOf {
    Generator
    Meaning
}

impl SpliceOf {
    /// Whether a hole's fill is a node of the store the splice lands in, by its arena and index.
    fn holds_nodes() -> bool { match self { .Meaning -> true, .Generator -> false } }

    /// Whether the copied nodes keep the spans their template was written at.
    fn spanned_home() -> bool { match self { .Generator -> true, .Meaning -> false } }
}

