/// THE DOOR LAW, AND THE ONE PLACE A PATH IS CHOSEN: every command that reads a program — `build`,
/// `run`, `check`, `test` — takes the program layer, for a package's directory and for a lone file
/// alike, or refuses once, naming what the layer cannot do yet; it never takes the old path instead.
/// `AVRA_PROGRAM=0` alone takes the old path.
// LICENSED input.debug_flag: which path answers during the switch, never an input of an answer
export fn program_door() -> bool { env("AVRA_PROGRAM") != "0" }

/// THE NET, chosen beside the path: on the program layer the old path judges each program first — a
/// build what its own build reads, a check what its own check reads (`NetJudge`) — and what it
/// refuses stops there in its words; the program layer builds only what it
/// accepts, so a refusal the layer says after it is the layer's defect. `AVRA_PROGRAM_NET=0` takes
/// the net away.
// LICENSED input.debug_flag: which path answers during the switch, never an input of an answer
export fn program_net() -> bool { program_door() && env("AVRA_PROGRAM_NET") != "0" }

/// What the old path judges a program by, as the old path's own command for it reads it: a build or a run,
/// the entry's reach, analysed, before anything is lowered; a check, the whole package as its entry
/// sees it; a test, the whole package the path stands in, which its suite reads with no entry of its
/// own.
export enum NetJudge {
    Build
    Check
    Proved
}

/// What the net said of a program before the program layer reads it: nothing, where the net is off;
/// the old path's acceptance; or its refusal, in its words.
export enum NetSaid {
    Off
    Accepted
    Refused(report: string)
}

/// The net over `paths`: the old path's judgement of each, as `judge` names it.
export fn net_said(paths: List<string>, judge: NetJudge) -> NetSaid {
    if !program_net() { return NetSaid.Off }
    let report? = paths.find_map((p) -> net_report(p, judge)) else { return NetSaid.Accepted }
    NetSaid.Refused(report)
}

/// THE NET STEPS ASIDE for a program that uses a form only the program layer builds (`uses`, as the
/// layer reads them): the old path never learned it, so its refusal is no verdict, and the layer's
/// answer is the program's. Any other refusal stops the command, said in the old path's words: the
/// exit it left by. `uses` is asked only of a program the old path refused.
export fn net_stops(said: NetSaid, uses: fn() -> List<NewOnly>) -> int? {
    match said {
        .Refused(report) -> if uses().is_empty() { said_refused(report) } else { null },
        _ -> null,
    }
}

/// Whether the net vouches for a program the layer refuses, so the refusal is the layer's defect: the
/// old path accepted it, and it uses no form only the layer builds (`uses`), whose meaning the old path
/// never learned.
export fn net_vouches(said: NetSaid, uses: fn() -> List<NewOnly>) -> bool { said is .Accepted && uses().is_empty() }

/// The old path's refusal, said: exit 1.
fn said_refused(report: string) -> int {
    println(report)
    1
