/// The mark an identity type wears, and the one licensing a plain field.
const IDENTITY: string = "identity"

const PLAIN_FIELD: string = "plain_field"

/// Every field of an `@identity` record the written item `at` of `file` declares that a copy's
/// write could fork: where the record stands, the field, and its type.
fn plain_identity_fields(engine: QueryEngine, file: SourceFileAddress, at: int) -> List<Found> {
    let worn = file_marks(engine, file).worn
    let records = [d for d in file_declares_at(engine, file, at).names if d.item == at && d.kind == ItemKind.Record && worn.any(it.name == d.name && it.mark == IDENTITY)]
    if records.is_empty() { return [] }
    let item = read_item(engine, file, at)
    [Found { at: record_place(item, r.name), args: [f.name, f.ty!.spelled()] } for r in records for f in record_signature(engine, file, r.name)?.fields ?? [] if f.ty != null && !f.state && !licensed(engine, file, r.name, f.name) && !shared(engine, f.ty!)]
}

/// Where the record `name` the item `item` declares stands.
fn record_place(item: ReadItem, name: string) -> Span? {
    let s? = item.stmts.find((st) -> item.store.struct_parts(st)?.name == name) else { return null }
