/// What the innermost scope holds, ended as a normal end ends it.
mut fn joined() { self.ended_in(self.endings.get().last() ?? [], Leaving.Plain) }

/// What the body's own frame holds, ended as the body's normal end ends it, answering `gives`
/// where it answers one: nothing the body made outlives it.
mut fn body_ended(gives: Reg?) {
    self.ended_in(self.endings.get().first() ?? [], if gives == null { Leaving.Plain } else { Leaving.Answering(gives!) })
    self.endings.set_at(0, no_endings())
}

